/*
 * Capture 39 proved that committing and launching the leading reverse was
 * not sufficient: T15 reached the first in-route reversal, issued zero, and
 * never produced the second direction/positive-speed pair.  Exercise the
 * complete first reverse leg so the historical T14 HEAD_ON latch cannot
 * silently block the committed handoff.
 */
static int check_capture39_second_reversal_relaunches(void) {
        if (run_real_head_on_reroute_second_go_at_post_coast_sensor(
                    "capture39/C7", "C7", 5,
                    30, 4, 1, 0, 0) < 0) {
                return -1;
        }
        int slot = find_train_job(15);
        if (slot < 0) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        if (runtime->route.reversal_count < 2 ||
            job->reversals_completed != 2 ||
            job->state != TC2_JOB_REVERSING) {
                fprintf(stderr,
                        "capture39 fixture lacked second reversal "
                        "state=%d reversals=%d completed=%d offsets=%d/%d\n",
                        job->state, runtime->route.reversal_count,
                        job->reversals_completed,
                        job->current_route_offset,
                        runtime->leg_end_offset);
                return -1;
        }
        int reverse_before = mock_reverse_calls;
        int positive_before = mock_positive_commands_by_train[15];
        int settle = mock_now;
        for (int elapsed = 0; elapsed <= 512; ++elapsed) {
                mock_now = tick_after(settle, elapsed);
                run_dispatch_server_tick_for_test(mock_now);
                if (job->state == TC2_JOB_FAILED) break;
                if (mock_reverse_calls > reverse_before &&
                    mock_positive_commands_by_train[15] > positive_before &&
                    job->state == TC2_JOB_RUNNING) {
                        return 0;
                }
        }
        fprintf(stderr,
                "capture39 second reversal stayed stopped "
                "state=%d failure=%d conflict=%d:%d reverse=%d/%d "
                "positive=%d/%d blockers=%d generation=%u replace=%u\n",
                job->state, job->failure_reason,
                job->conflict_train, job->conflict_node,
                reverse_before, mock_reverse_calls,
                positive_before,
                mock_positive_commands_by_train[15],
                traffic_blocker_any(slot), job->plan_generation,
                runtime->replace_expected_generation);
        return -1;
}

enum capture33_carry_overlap_case {
        CAPTURE33_OLD_HEAD_ON_CARRY = 0,
        CAPTURE33_THIRD_TRAIN_CARRY = 1,
        CAPTURE33_OLD_HEAD_ON_REVERSE_MOTION = 2
};

/*
 * Reproduce capture 33 only through its final, stationary D7/D10 state.
 * Keeping this setup separate from the end-to-end helper lets the focused
 * cases inject one reservation immediately before process_pending_retargets().
 * A complete scheduler tick would first compact the synthetic owner and stop
 * testing the candidate-authority distinction this regression is about.
 */
static int setup_capture33_post_coast_head_on_hold(
        int *train14_slot_out, int *train15_slot_out,
        unsigned int sensor_sequences[2]) {
        int train14_slot = -1;
        int train15_slot = -1;
        if (!train14_slot_out || !train15_slot_out ||
            !sensor_sequences ||
            setup_real_scheduler_a_d1_d_d7_head_on_hold(
                    &train14_slot, &train15_slot,
                    sensor_sequences) < 0) {
                return -1;
        }

        int coast_start_tick = mock_now;
        mock_now = tick_after(coast_start_tick, 9);
        if (inject_named_route_sensor_for_test(
                    train14_slot, "E7", mock_now,
                    &sensor_sequences[0]) < 0) {
                return -1;
        }
        run_dispatch_server_tick_for_test(mock_now);

        mock_now = tick_after(coast_start_tick, 159);
        if (inject_named_route_sensor_for_test(
                    train15_slot, "D10", mock_now,
                    &sensor_sequences[1]) < 0) {
                return -1;
        }
        run_dispatch_server_tick_for_test(mock_now);

        mock_now = tick_after(coast_start_tick, 169);
        if (inject_named_route_sensor_for_test(
                    train14_slot, "D7", mock_now,
                    &sensor_sequences[0]) < 0) {
                return -1;
        }
        run_dispatch_server_tick_for_test(mock_now);
        mock_now = tick_after(mock_now, 1);
        run_dispatch_server_tick_for_test(mock_now);

        int d7 = TrackFindNodeByName(dispatch_track, "D7");
        int d10 = TrackFindNodeByName(dispatch_track, "D10");
        if (d7 < 0 || d10 < 0 ||
            dispatch_jobs[train14_slot].state !=
                    TC2_JOB_TRAFFIC_HOLD ||
            dispatch_jobs[train15_slot].state !=
                    TC2_JOB_TRAFFIC_HOLD ||
            dispatch_jobs[train14_slot].current_node != d7 ||
            dispatch_jobs[train14_slot].current_route_offset != 6 ||
            dispatch_jobs[train15_slot].current_node != d10 ||
            dispatch_jobs[train15_slot].current_route_offset != 10 ||
            !traffic_blocker_contains_train(train15_slot, 14) ||
            traffic_blocker_reason_for_train(train15_slot, 14) !=
                    TC2_TRAFFIC_HEAD_ON) {
                fprintf(stderr,
                        "capture33 focused fixture did not reach the exact "
                        "D7/D10 HEAD_ON hold\n");
                return -1;
        }
        *train14_slot_out = train14_slot;
        *train15_slot_out = train15_slot;
        return 0;
}

static int capture33_node_is_pair(
        int node, int expected, int expected_reverse) {
        return node == expected || node == expected_reverse;
}

static int run_capture33_carry_overlap_case(
        enum capture33_carry_overlap_case overlap_case) {
        int train14_slot = -1;
        int train15_slot = -1;
        unsigned int sensor_sequences[2];
        if (setup_capture33_post_coast_head_on_hold(
                    &train14_slot, &train15_slot,
                    sensor_sequences) < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *train14 =
                &dispatch_jobs[train14_slot];
        tc2_dispatch_job_snapshot *train15 =
                &dispatch_jobs[train15_slot];
        tc2_dispatch_runtime *runtime15 =
                &dispatch_runtime[train15_slot];
        int d10 = TrackFindNodeByName(dispatch_track, "D10");
        int d9 = TrackFindNodeByName(dispatch_track, "D9");
        int e12 = TrackFindNodeByName(dispatch_track, "E12");
        int e11 = TrackFindNodeByName(dispatch_track, "E11");
        int mr8 = TrackFindNodeByName(dispatch_track, "MR8");
        int br8 = TrackFindNodeByName(dispatch_track, "BR8");
        if (d10 < 0 || d9 < 0 || e12 < 0 || e11 < 0 ||
            mr8 < 0 || br8 < 0 ||
            physical_reverse_index(d10) != d9 ||
            physical_reverse_index(mr8) != br8 ||
            physical_reverse_index(e12) != e11) {
                return -1;
        }

        /*
         * D10's synthetic 302 mm stopped guard reaches the 316 mm edge
         * endpoint MR8.  Reservation availability also checks MR8's physical
         * reverse BR8, so either owner blocks the same rail resource.  Neither
         * node belongs to the reverse motion route D10 -> D9 -> E12; use the
         * measured old carry instead of this forward-looking synthetic guard.
         */
        track_route synthetic_stopped_guard;
        if (build_route_slice(
                    &runtime15->route,
                    train15->current_route_offset,
                    train15->current_route_offset,
                    &synthetic_stopped_guard) < 0 ||
            append_forward_guard_reachable(
                    &synthetic_stopped_guard, d10,
                    TC2_TRAIN_HALF_LENGTH_MM +
                            TC2_TRAFFIC_FOLLOWING_STOP_CLEARANCE_MM) < 0 ||
            append_paired_turnout_resources(
                    &synthetic_stopped_guard) < 0 ||
            !route_contains_node(&synthetic_stopped_guard, mr8)) {
                fprintf(stderr,
                        "capture33 fixture no longer exposes the MR8/BR8 "
                        "synthetic carry overlap\n");
                return -1;
        }

        unsigned int old_generation = train15->plan_generation;
        int old_destination = train15->target_node;
        int positive_before = mock_positive_commands_by_train[15];
        int reverse_before = mock_reverse_calls;
        tc2_dispatch_request request;
        clear_request(&request, TC2_DISPATCH_MSG_STAGE);
        request.train = 15;
        request.start_index = TC2_DISPATCH_START_CURRENT;
        request.speed = 30;
        request.destination_index = 4;
        request.reserved |=
                TC2_DISPATCH_REQUEST_FORCE_REVERSE_FIRST;
        if (stage_job(&request) < 0 ||
            !runtime15->retarget_pending ||
            runtime15->retarget_armed) {
                return -1;
        }
        arm_pending_retarget_like_go(train15_slot);

        int injected_owner =
                overlap_case == CAPTURE33_THIRD_TRAIN_CARRY ?
                18 : 14;
        int injected_node =
                overlap_case == CAPTURE33_OLD_HEAD_ON_REVERSE_MOTION ?
                e12 : mr8;
        int injected_reverse =
                overlap_case == CAPTURE33_OLD_HEAD_ON_REVERSE_MOTION ?
                e11 : br8;
        int motion_overlap =
                overlap_case ==
                        CAPTURE33_OLD_HEAD_ON_REVERSE_MOTION;
        if ((!motion_overlap &&
             (mock_reservations.owner_by_node[injected_node] != 0 ||
              mock_reservations.owner_by_node[injected_reverse] != 0)) ||
            (motion_overlap &&
             ((mock_reservations.owner_by_node[injected_node] != 0 &&
               mock_reservations.owner_by_node[injected_node] != 15) ||
              (mock_reservations.owner_by_node[injected_reverse] != 0 &&
               mock_reservations.owner_by_node[injected_reverse] != 15)))) {
                fprintf(stderr,
                        "capture33 focused overlap nodes were not free "
                        "before injection: %s=%d %s=%d\n",
                        dispatch_track[injected_node].name,
                        mock_reservations.owner_by_node[injected_node],
                        dispatch_track[injected_reverse].name,
                        mock_reservations.owner_by_node[injected_reverse]);
                return -1;
        }
        mock_reservations.owner_by_node[injected_node] =
                injected_owner;
        mock_reservations.owner_by_node[injected_reverse] =
                injected_owner;
        if (injected_owner == 18) {
                mock_reservations.destination_by_train[18] =
                        injected_node;
                mock_reservations.generation_by_train[18] = 77;
        }

        mock_now = tick_after(mock_now, 1);
        process_pending_retargets(mock_now);
        if (overlap_case != CAPTURE33_OLD_HEAD_ON_CARRY) {
                if (train15->plan_generation != old_generation ||
                    train15->target_node != old_destination ||
                    train15->state != TC2_JOB_TRAFFIC_HOLD ||
                    !runtime15->retarget_pending ||
                    !runtime15->retarget_armed ||
                    (train15->conflict_train != 0 &&
                     (train15->conflict_train != injected_owner ||
                      !capture33_node_is_pair(
                              train15->conflict_node,
                              injected_node, injected_reverse))) ||
                    mock_reverse_calls != reverse_before ||
                    mock_positive_commands_by_train[15] !=
                            positive_before ||
                    mock_reservations.owner_by_node[injected_node] !=
                            injected_owner ||
                    mock_reservations.owner_by_node[injected_reverse] !=
                            injected_owner) {
                        fprintf(stderr,
                                "capture33 non-peer/motion overlap was not "
                                "retained safely case=%d state=%d "
                                "generation=%u/%u conflict=%d:%s "
                                "pending=%d/%d\n",
                                overlap_case, train15->state,
                                train15->plan_generation,
                                old_generation,
                                train15->conflict_train,
                                train15->conflict_node >= 0 ?
                                        dispatch_track[
                                                train15->conflict_node]
                                                .name :
                                        "none",
                                runtime15->retarget_pending,
                                runtime15->retarget_armed);
                        return -1;
                }
                return 0;
        }

        unsigned int expected_generation = old_generation + 1;
        if (expected_generation == 0) expected_generation = 1;
        if (train15->plan_generation != expected_generation ||
            mock_reservations.generation_by_train[15] !=
                    expected_generation ||
            runtime15->retarget_pending ||
            runtime15->retarget_armed ||
            train15->state != TC2_JOB_PREPARING ||
            !runtime15->force_reverse_first ||
            !runtime15->prelaunch_reverse_pending ||
            runtime15->route.node_count < 3 ||
            runtime15->route.nodes[0] != d10 ||
            runtime15->route.nodes[1] != d9 ||
            runtime15->route.nodes[2] != e12 ||
            !route_starts_with_reversal(&runtime15->route) ||
            route_contains_node(&runtime15->route, mr8) ||
            route_contains_node(&runtime15->route, br8) ||
            route_contains_node(&runtime15->safety_footprint, mr8) ||
            route_contains_node(&runtime15->safety_footprint, br8) ||
            mock_reservations.owner_by_node[mr8] != 14 ||
            mock_reservations.owner_by_node[br8] != 14 ||
            train14->command_speed != 0 ||
            mock_reverse_calls != reverse_before ||
            mock_positive_commands_by_train[15] != positive_before) {
                fprintf(stderr,
                        "capture33 old-peer carry overlap did not commit "
                        "the D10->D9->E12 reverse plan state=%d "
                        "generation=%u/%u conflict=%d:%s "
                        "carry=%d/%d route=%s/%s/%s reverse=%d/%d\n",
                        train15->state, train15->plan_generation,
                        expected_generation,
                        train15->conflict_train,
                        train15->conflict_node >= 0 ?
                                dispatch_track[
                                        train15->conflict_node].name :
                                "none",
                        route_contains_node(
                                &runtime15->carry_ambiguity_footprint,
                                mr8),
                        route_contains_node(
                                &runtime15->carry_ambiguity_footprint,
                                br8),
                        runtime15->route.node_count > 0 ?
                                dispatch_track[
                                        runtime15->route.nodes[0]].name :
                                "none",
                        runtime15->route.node_count > 1 ?
                                dispatch_track[
                                        runtime15->route.nodes[1]].name :
                                "none",
                        runtime15->route.node_count > 2 ?
                                dispatch_track[
                                        runtime15->route.nodes[2]].name :
                                "none",
                        reverse_before, mock_reverse_calls);
                return -1;
        }
        for (int offset = 0;
             offset < runtime15->safety_footprint.node_count;
             ++offset) {
                int node = runtime15->safety_footprint.nodes[offset];
                if (mock_reservations.owner_by_node[node] != 15) {
                        fprintf(stderr,
                                "capture33 committed safety footprint lost "
                                "authority at %s owner=%d\n",
                                dispatch_track[node].name,
                                mock_reservations.owner_by_node[node]);
                        return -1;
                }
        }

        int preparing_tick = mock_now;
        for (int elapsed = 1;
             elapsed <= 128 &&
                     mock_reverse_calls == reverse_before;
             ++elapsed) {
                mock_now = tick_after(preparing_tick, elapsed);
                process_preparing_jobs(mock_now);
                if (train15->state == TC2_JOB_FAILED ||
                    mock_positive_commands_by_train[15] !=
                            positive_before) {
                        return -1;
                }
        }
        if (mock_reverse_calls != reverse_before + 1 ||
            runtime15->prelaunch_reverse_pending ||
            mock_positive_commands_by_train[15] != positive_before) {
                fprintf(stderr,
                        "capture33 old-peer carry escape did not send exactly "
                        "one CMD05 before launch reverse=%d/%d positive=%d/%d\n",
                        reverse_before, mock_reverse_calls,
                        positive_before,
                        mock_positive_commands_by_train[15]);
                return -1;
        }
        return 0;
}

static int check_capture33_old_peer_carry_overlap_is_reverse_safe(void) {
        if (run_capture33_carry_overlap_case(
                    CAPTURE33_OLD_HEAD_ON_CARRY) < 0 ||
            run_capture33_carry_overlap_case(
                    CAPTURE33_THIRD_TRAIN_CARRY) < 0 ||
            run_capture33_carry_overlap_case(
                    CAPTURE33_OLD_HEAD_ON_REVERSE_MOTION) < 0) {
                return -1;
        }
        return 0;
}

static int check_real_head_on_reroute_second_go_launches_after_turnout_wait(
        void) {
        if (run_real_head_on_reroute_second_go_at_post_coast_sensor(
                    "capture26/E11", "E11", 9,
                    80, 4, 0, 1, 0) < 0) {
                report_real_post_coast_reroute_failure(
                        "capture26/E11");
                return -1;
        }
        if (check_capture27_d10_reroute_selects_reverse_escape() < 0) {
                return -1;
        }
        if (check_capture28_low_speed_d8_still_reverses() < 0) {
                return -1;
        }
        if (check_capture32_speed30_d5_is_reverse_only() < 0) {
                return -1;
        }
        if (check_capture33_stationary_guard_does_not_block_reverse() < 0) {
                return -1;
        }
        if (check_capture35_c7_estimate_can_reverse_to_d5() < 0) {
                return -1;
        }
        if (check_capture39_second_reversal_relaunches() < 0) {
                return -1;
        }
        return check_capture33_old_peer_carry_overlap_is_reverse_safe();
}

static int check_head_on_deadlock_exposes_two_current_recoveries(void) {
        int successful_options = 0;
        for (int option = 0; option < 2; ++option) {
                int recovering_train =
                        option == 0 ? 13 : 14;
                int peer_train =
                        option == 0 ? 14 : 13;
                int option_succeeded = 0;
                for (int destination = 1;
                     destination <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++destination) {
                        int status =
                                try_head_on_current_recovery_option(
                                        recovering_train,
                                        peer_train,
                                        destination, 0);
                        if (status < 0) return -1;
                        if (status == 0) {
                                option_succeeded = 1;
                                break;
                        }
                }
                if (!option_succeeded) {
                        fprintf(stderr,
                                "head-on deadlock did not expose CURRENT "
                                "recovery option for T%d while T%d stayed "
                                "stopped\n",
                                recovering_train, peer_train);
                        return -1;
                }
                ++successful_options;
        }
        return successful_options == 2 ? 0 : -1;
}

static int check_non_deadlock_collision_current_retarget_recovers_both(void) {
        for (int destination = 1;
             destination <
                     TC2_DISPATCH_DESTINATION_COUNT;
             ++destination) {
                int status =
                        try_head_on_current_recovery_option(
                                13, 14, destination, 1);
                if (status < 0) return -1;
                if (status > 0) continue;

                int recovering_slot =
                        find_train_job(13);
                int survivor_slot =
                        find_train_job(14);
                if (recovering_slot < 0 ||
                    survivor_slot < 0) {
                        return -1;
                }
                tc2_dispatch_job_snapshot *recovering =
                        &dispatch_jobs[recovering_slot];
                tc2_dispatch_runtime *recovery_runtime =
                        &dispatch_runtime[recovering_slot];
                tc2_dispatch_job_snapshot *survivor =
                        &dispatch_jobs[survivor_slot];
                tc2_dispatch_runtime *survivor_runtime =
                        &dispatch_runtime[survivor_slot];
                int survivor_frozen_node =
                        survivor->current_node;
                int64_t survivor_frozen_anchor_um =
                        survivor_runtime
                                ->motion_anchor_distance_um;
                int64_t recovering_frozen_anchor_um =
                        recovery_runtime
                                ->motion_anchor_distance_um;
                int origin =
                        recovery_runtime->leg_start_offset;
                tc2_route_sensor_point first_sensor;
                tc2_route_sensor_point second_sensor;
                if (recovering->state != TC2_JOB_RUNNING ||
                    !recovery_runtime
                             ->head_on_recovery_active ||
                    recovery_runtime
                            ->head_on_recovery_cleared ||
                    !recovery_runtime
                             ->carry_ambiguity_active ||
                    Tc2RouteExpectedSensors(
                            dispatch_track,
                            &recovery_runtime->route,
                            recovery_runtime
                                    ->monitor.confirmed_offset,
                            recovery_runtime
                                    ->monitor_terminal_offset,
                            &first_sensor,
                            &second_sensor) < 2 ||
                    first_sensor.route_offset <= origin ||
                    second_sensor.route_offset <=
                            first_sensor.route_offset ||
                    second_sensor.route_offset >
                            recovery_runtime
                                    ->authority_end_offset) {
                        continue;
                }
                int clear_anchor =
                        first_sensor.route_offset;
                recovery_runtime->reservation_anchor_offset =
                        clear_anchor;
                int clear_tail = footprint_tail_offset(
                        recovery_runtime, recovering);
                recovery_runtime->reservation_anchor_offset =
                        origin;
                if (clear_tail <= origin) {
                        continue;
                }

                /*
                 * The peer keeps its real physical node throughout recovery.
                 * A prior version moved it to a convenient unrelated node,
                 * which could hide a position rollback and did not exercise
                 * the operator's actual CURRENT/go recovery workflow.
                 */
                int survivor_node = survivor->current_node;
                int survivor_reverse =
                        physical_reverse_index(
                                survivor_node);
                if ((dispatch_track[survivor_node].type !=
                             NODE_SENSOR &&
                     dispatch_track[survivor_node].type !=
                             NODE_ENTER &&
                     dispatch_track[survivor_node].type !=
                             NODE_EXIT) ||
                    !dispatch_track[survivor_node]
                             .edge[DIR_AHEAD].dest ||
                    dispatch_track[survivor_node]
                                    .edge[DIR_AHEAD]
                                    .dist <=
                            0 ||
                    route_contains_node(
                            &recovery_runtime->route,
                            survivor_node) ||
                    (survivor_reverse >= 0 &&
                     route_contains_node(
                             &recovery_runtime->route,
                             survivor_reverse))) {
                        continue;
                }
                int survivor_target =
                        (int)(dispatch_track[
                                      survivor_node]
                                      .edge[DIR_AHEAD]
                                      .dest -
                              dispatch_track);
                track_route survivor_window = {0};
                survivor_window.node_count = 2;
                survivor_window.nodes[0] =
                        survivor_node;
                survivor_window.nodes[1] =
                        survivor_target;
                survivor_window.distance_mm =
                        dispatch_track[survivor_node]
                                .edge[DIR_AHEAD].dist;
                track_reservation_conflict survivor_conflict;
                unsigned int survivor_generation_after = 0;
                if (TrackReservationServerReplaceWindowExpected(
                            dispatch_reservation_tid,
                            &survivor_window,
                            survivor->train,
                            survivor->target_node,
                            survivor->plan_generation,
                            survivor_target,
                            &survivor_conflict,
                            &survivor_generation_after) != 0 ||
                    survivor_generation_after == 0 ||
                    survivor_generation_after ==
                            survivor->plan_generation) {
                        continue;
                }
                survivor->plan_generation =
                        survivor_generation_after;
                survivor->target_node =
                        survivor_target;
                survivor->current_node = survivor_node;
                survivor->current_route_offset = 0;
                survivor->target_route_offset = 1;
                survivor->destination_route_offset = 1;
                survivor->destination_distance_mm =
                        dispatch_track[survivor_node]
                                .edge[DIR_AHEAD].dist;
                survivor_runtime->route.node_count = 2;
                survivor_runtime->route.nodes[0] =
                        survivor_node;
                survivor_runtime->route.nodes[1] =
                        survivor_target;
                survivor_runtime->route.distance_mm =
                        survivor
                                ->destination_distance_mm;
                survivor_runtime->route_valid = 1;
                survivor_runtime->start_node =
                        survivor_node;
                survivor_runtime->leg_start_offset = 0;
                survivor_runtime->leg_end_offset = 1;
                survivor_runtime->monitor_terminal_offset = 1;
                survivor_runtime->monitor.confirmed_offset = 0;
                survivor_runtime
                        ->monitor.confirmed_distance_mm = 0;
                survivor_runtime
                        ->reservation_anchor_offset = 0;
                survivor_runtime->rolling_authority_active = 1;
                survivor_runtime->authority_end_offset = 1;
                survivor_runtime
                        ->authority_center_ceiling_mm =
                        survivor
                                ->destination_distance_mm;
                survivor->state =
                        TC2_JOB_TRAFFIC_HOLD;
                survivor->command_speed = 0;
                survivor->hold_active = 1;
                survivor->traffic_hold_active = 1;
                survivor->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                survivor->traffic_peer_train =
                        recovering->train;
                survivor->traffic_hold_distance_um = 0;
                survivor_runtime->command_speed = 0;
                survivor_runtime->motion_speed_ceiling = 20;
                survivor_runtime->stop_purpose =
                        TC2_STOP_TRAFFIC;
                survivor_runtime->traffic_reason =
                        TC2_TRAFFIC_HEAD_ON;
                survivor_runtime->traffic_peer_train =
                        recovering->train;
                survivor_runtime->traffic_resume_speed = 20;
                survivor_runtime->traffic_hold_distance_um = 0;
                unsigned int survivor_generation =
                        survivor->plan_generation;
                unsigned int recovering_generation =
                        recovering->plan_generation;
                if (survivor_generation == 0 ||
                    recovering_generation == 0 ||
                    mock_reservations
                                    .generation_by_train[
                                            survivor->train] !=
                            survivor_generation ||
                    mock_reservations
                                    .generation_by_train[
                                            recovering->train] !=
                            recovering_generation ||
                    mock_reservations
                                    .destination_by_train[
                                            survivor->train] !=
                            survivor->target_node ||
                    mock_reservations
                                    .destination_by_train[
                                            recovering->train] !=
                            recovering->target_node) {
                        fprintf(stderr,
                                "CURRENT recovery fixture did not retain two "
                                "independent nonzero reservation generations\n");
                        return -1;
                }
                tc2_dispatch_job_snapshot recovering_before_probe =
                        *recovering;
                tc2_dispatch_runtime recovery_before_probe =
                        *recovery_runtime;
                recovering->current_route_offset =
                        second_sensor.route_offset;
                recovering->current_node =
                        second_sensor.node_index;
                recovering->confirmed_distance_mm =
                        second_sensor.distance_mm;
                recovering->estimated_distance_um =
                        (int64_t)second_sensor.distance_mm *
                                1000;
                recovery_runtime->monitor.confirmed_offset =
                        second_sensor.route_offset;
                recovery_runtime
                        ->monitor.confirmed_distance_mm =
                        second_sensor.distance_mm;
                recovery_runtime->motion_anchor_distance_um =
                        (int64_t)second_sensor.distance_mm *
                                1000;
                recovery_runtime->motion_anchor_tick =
                        mock_now;
                recovery_runtime->motion_anchor_from_traffic = 0;
                tc2_live_traffic_relation clear_relation;
                int clear_relation_status =
                        live_traffic_relation_for_pair(
                                recovering_slot,
                                survivor_slot,
                                tick_after(mock_now, 1),
                                &clear_relation);
                *recovering = recovering_before_probe;
                *recovery_runtime = recovery_before_probe;
                if (clear_relation_status < 0) return -1;
                if (clear_relation.valid) continue;

                int carried_node =
                        recovery_runtime
                                ->carry_ambiguity_footprint
                                .nodes[0];
                int updates_before =
                        mock_window_update_calls_by_train[
                                recovering->train];
                train_sensor_attributed_event_t first_event;
                first_event.sensor_index =
                        first_sensor.node_index;
                first_event.train = recovering->train;
                first_event.generation =
                        recovering->plan_generation;
                first_event.sequence =
                        recovery_runtime
                                ->last_journal_sequence + 1;
                if (first_event.sequence == 0) {
                        ++first_event.sequence;
                }
                first_event.timestamp = 1;
                int first_advance_mm =
                        first_sensor.distance_mm -
                        recovery_runtime->monitor
                                .confirmed_distance_mm;
                int first_travel_ticks =
                        Tc2MotionFastTravelTicks(
                                recovering->speed,
                                first_advance_mm);
                if (first_advance_mm <= 0 ||
                    first_travel_ticks < 0) {
                        return -1;
                }
                int first_event_tick =
                        recovery_runtime
                                        ->last_confirmed_tick >=
                                0 ?
                        tick_after(
                                recovery_runtime
                                        ->last_confirmed_tick,
                                first_travel_ticks + 2) :
                        tick_after(
                                mock_now,
                                first_travel_ticks + 2);
                first_event.arrival_tick =
                        first_event_tick;
                if (process_sensor_observation(
                            recovering_slot,
                            &first_event,
                            first_event_tick,
                            first_event_tick) < 0 ||
                    recovery_runtime
                                    ->reservation_anchor_offset !=
                            origin ||
                    !recovery_runtime
                             ->carry_ambiguity_active ||
                    recovery_runtime
                            ->head_on_recovery_cleared ||
                    mock_reservations.owner_by_node[
                            carried_node] !=
                            recovering->train ||
                    mock_window_update_calls_by_train[
                            recovering->train] !=
                            updates_before + 1) {
                        fprintf(stderr,
                                "one downstream CURRENT anchor released "
                                "the carried HEAD_ON corridor too early\n");
                        return -1;
                }
                process_traffic_safety(
                        first_event_tick);
                if (survivor->state !=
                            TC2_JOB_TRAFFIC_HOLD ||
                    survivor_runtime->traffic_reason !=
                            TC2_TRAFFIC_HEAD_ON) {
                        fprintf(stderr,
                                "insufficient CURRENT tail evidence woke "
                                "the stopped HEAD_ON survivor\n");
                        return -1;
                }

                train_sensor_attributed_event_t second_event;
                second_event.sensor_index =
                        second_sensor.node_index;
                second_event.train = recovering->train;
                second_event.generation =
                        recovering->plan_generation;
                second_event.sequence =
                        first_event.sequence + 1;
                if (second_event.sequence == 0) {
                        ++second_event.sequence;
                }
                second_event.timestamp = 2;
                int second_advance_mm =
                        second_sensor.distance_mm -
                        first_sensor.distance_mm;
                int second_travel_ticks =
                        Tc2MotionFastTravelTicks(
                                recovering->speed,
                                second_advance_mm);
                if (second_advance_mm <= 0 ||
                    second_travel_ticks < 0) {
                        return -1;
                }
                int second_event_tick =
                        tick_after(
                                first_event_tick,
                                second_travel_ticks + 2);
                second_event.arrival_tick =
                        second_event_tick;
                int braking =
                        Tc2MotionBrakingDistanceMm(
                                recovering->speed);
                if (process_sensor_observation(
                            recovering_slot,
                            &second_event,
                            second_event_tick,
                            second_event_tick) < 0 ||
                    recovery_runtime
                                    ->reservation_anchor_offset !=
                            clear_anchor ||
                    recovery_runtime
                            ->carry_ambiguity_active ||
                    !recovery_runtime
                              ->head_on_recovery_cleared ||
                    mock_reservations.owner_by_node[
                            carried_node] ==
                            recovering->train ||
                    mock_window_update_calls_by_train[
                            recovering->train] !=
                            updates_before + 2 ||
                    braking < 0 ||
                    recovery_runtime
                                    ->authority_center_ceiling_mm -
                                    second_sensor.distance_mm <
                            braking) {
                        fprintf(stderr,
                                "tail+release-margin crossing did not "
                                "generation-CAS release the carried "
                                "HEAD_ON corridor\n");
                        return -1;
                }
                if (recovering->state == TC2_JOB_FAILED) {
                        fprintf(stderr,
                                "CURRENT recovery failed before survivor wake "
                                "failure=%d\n",
                                recovering->failure_reason);
                        return -1;
                }
                process_traffic_safety(
                        tick_after(second_event_tick, 1));
                if (recovering->state != TC2_JOB_RUNNING ||
                    survivor->state != TC2_JOB_RUNNING ||
                    recovering->command_speed <= 0 ||
                    survivor->command_speed <= 0 ||
                    survivor_runtime->traffic_reason !=
                            TC2_TRAFFIC_NONE ||
                    survivor->traffic_reason !=
                            TC2_TRAFFIC_NONE ||
                    mock_reservations
                                    .generation_by_train[
                                            survivor->train] !=
                            survivor_generation ||
                    mock_reservations
                                    .generation_by_train[
                                            recovering->train] !=
                            recovering_generation ||
                    mock_reservations
                                    .destination_by_train[
                                            survivor->train] !=
                            survivor->target_node ||
                    mock_reservations
                                    .destination_by_train[
                                            recovering->train] !=
                            recovering->target_node) {
                        fprintf(stderr,
                                "released CURRENT recovery did not leave both "
                                "managed trains running state=%d/%d "
                                "reason=%d/%d failure=%d/%d\n",
                                recovering->state,
                                survivor->state,
                                recovery_runtime
                                        ->traffic_reason,
                                survivor_runtime
                                        ->traffic_reason,
                                recovering->failure_reason,
                                survivor->failure_reason);
                        return -1;
                }
                if (recovery_runtime
                                    ->motion_anchor_distance_um <
                            recovering_frozen_anchor_um ||
                    survivor->estimated_distance_um <
                            survivor_frozen_anchor_um ||
                    survivor_runtime
                                    ->motion_anchor_distance_um <
                            survivor_frozen_anchor_um ||
                    recovering->current_route_offset <
                            second_sensor.route_offset ||
                    recovering->current_node !=
                            second_sensor.node_index ||
                    survivor->current_node !=
                            survivor_frozen_node) {
                        fprintf(stderr,
                                "CURRENT collision recovery rolled a train "
                                "position backward\n");
                        return -1;
                }
                return 0;
        }
        fprintf(stderr,
                "no HEAD_ON CURRENT recovery fixture contained enough "
                "bounded authority to prove delayed carry release\n");
        return -1;
}

static int check_one_head_on_survivor_waits_for_remove_release(
        int survivor_train, int removed_train) {
        int survivor_slot = -1;
        int peer_slot = -1;
        int peer_node = -1;
        if (setup_head_on_current_recovery_pair(
                    survivor_train, removed_train, &survivor_slot,
                    &peer_slot, &peer_node) < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *survivor =
                &dispatch_jobs[survivor_slot];
        tc2_dispatch_runtime *survivor_runtime =
                &dispatch_runtime[survivor_slot];
        tc2_dispatch_job_snapshot *peer =
                &dispatch_jobs[peer_slot];
        tc2_dispatch_runtime *peer_runtime =
                &dispatch_runtime[peer_slot];

        peer->state = TC2_JOB_TRAFFIC_HOLD;
        peer->command_speed = 0;
        peer->traffic_hold_active = 1;
        peer->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        peer->traffic_peer_train = survivor->train;
        peer->traffic_hold_distance_um = 0;
        peer_runtime->stop_purpose = TC2_STOP_TRAFFIC;
        peer_runtime->command_speed = 0;
        peer_runtime->motion_speed_ceiling = 20;
        peer_runtime->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        peer_runtime->traffic_peer_train = survivor->train;
        peer_runtime->traffic_resume_speed = 20;
        peer_runtime->traffic_hold_distance_um = 0;

        if (cancel_job(peer->train) < 0) {
                return -1;
        }
        mock_now = peer_runtime->settle_at_tick;
        process_braking_and_reversing(mock_now);
        if (peer->state != TC2_JOB_STOPPED) {
                return -1;
        }

        int positive_before_remove =
                mock_positive_speed_calls +
                mock_direct_positive_speed_calls;
        process_traffic_safety(mock_now);
        if (survivor->state != TC2_JOB_TRAFFIC_HOLD ||
            survivor_runtime->traffic_reason !=
                    TC2_TRAFFIC_HEAD_ON ||
            mock_positive_speed_calls +
                    mock_direct_positive_speed_calls !=
                    positive_before_remove ||
            mock_reservations.owner_by_node[peer_node] !=
                    peer->train) {
                fprintf(stderr,
                        "HEAD_ON survivor resumed before the stopped peer "
                        "was removed and its reservation released\n");
                return -1;
        }

        int peer_train = peer->train;
        if (remove_job(peer_train) < 0 ||
            find_train_job(peer_train) >= 0 ||
            mock_reservations.owner_by_node[peer_node] != 0) {
                fprintf(stderr,
                        "peer remove did not release its reservation\n");
                return -1;
        }
        int resumed = 0;
        int release_tick = mock_now;
        for (int elapsed = 1;
             elapsed <= 200 && !resumed; ++elapsed) {
                int tick = tick_after(release_tick, elapsed);
                run_dispatch_server_tick_for_test(tick);
                resumed =
                        survivor->state == TC2_JOB_RUNNING &&
                        survivor->command_speed > 0 &&
                        mock_positive_speed_calls +
                                mock_direct_positive_speed_calls >
                                positive_before_remove;
        }
        if (!resumed ||
            survivor_runtime->traffic_reason ==
                    TC2_TRAFFIC_HEAD_ON) {
                fprintf(stderr,
                        "removing train %d did not restart supported "
                        "survivor %d state=%d reason=%d speed=%d\n",
                        removed_train, survivor_train,
                        survivor->state,
                        survivor_runtime->traffic_reason,
                        survivor->command_speed);
                fprintf(stderr,
                        " failure=%d authority=%d/%d hold=%lld "
                        "resume=%d conflict=%d:%d generation=%u\n",
                        survivor->failure_reason,
                        survivor_runtime->authority_end_offset,
                        survivor_runtime->route.node_count,
                        (long long)survivor_runtime
                                ->traffic_hold_distance_um,
                        survivor_runtime->traffic_resume_speed,
                        survivor->conflict_train,
                        survivor->conflict_node,
                        survivor->plan_generation);
                return -1;
        }
        return survivor_remains_running_after_remove(
                survivor_slot, removed_train, mock_now, 32,
                "HEAD_ON hold remove/restart");
}

static int check_head_on_survivor_waits_for_remove_release(void) {
        return check_one_head_on_survivor_waits_for_remove_release(
                       14, 15) < 0 ||
               check_one_head_on_survivor_waits_for_remove_release(
                       15, 14) < 0 ?
                -1 : 0;
}

/*
 * A survivor is not always still in TRAFFIC_HOLD when its peer is removed.
 * It may already own the next bounded authority and be READY, with the
 * positive command held behind the pairwise prelaunch gate.  Capture 19
 * exercised this state: remove15 released the rail, but T14 never received
 * another positive command.  Removal may clear only the released peer; the
 * next complete traffic pass must reopen the launch gate without rebuilding
 * the route or bypassing turnout settle.
 */
static int check_ready_survivor_rechecks_after_remove(void) {
        int survivor_slot = -1;
        int peer_slot = -1;
        int peer_node = -1;
        if (setup_head_on_current_recovery_pair(
                    14, 15, &survivor_slot,
                    &peer_slot, &peer_node) < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *survivor =
                &dispatch_jobs[survivor_slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[survivor_slot];
        tc2_dispatch_job_snapshot *peer =
                &dispatch_jobs[peer_slot];
        tc2_dispatch_runtime *peer_runtime =
                &dispatch_runtime[peer_slot];

        survivor->state = TC2_JOB_READY;
        survivor->command_speed = 0;
        survivor->traffic_hold_active = 1;
        survivor->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        survivor->traffic_peer_train = peer->train;
        runtime->command_speed = 0;
        runtime->stop_purpose = TC2_STOP_TRAFFIC;
        runtime->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        runtime->traffic_peer_train = peer->train;
        runtime->traffic_resume_speed = 20;
        runtime->planned_launch_speed = 20;
        runtime->authority_resume_pending = 1;
        runtime->prelaunch_traffic_blocked = 1;
        /*
         * Mirror the production HEAD_ON stop.  The scalar peer fields are
         * only a UI projection; physical removal is allowed to re-arm this
         * survivor only when the released train is present in the complete
         * blocker set.
         */
        if (traffic_blocker_add(
                    survivor_slot, peer->train,
                    TC2_TRAFFIC_HEAD_ON) < 0) {
                return -1;
        }
        peer->state = TC2_JOB_TRAFFIC_HOLD;
        peer->command_speed = 0;

        track_route route_before = runtime->route;
        unsigned int generation_before =
                survivor->plan_generation;
        int destination_before = survivor->target_node;
        int destination_index_before =
                survivor->destination_index;
        int64_t anchor_before =
                runtime->motion_anchor_distance_um;
        int positive_before =
                mock_positive_commands_by_train[14];
        int peer_positive_before =
                mock_positive_commands_by_train[15];
        if (survivor->ready_at_tick > mock_now) {
                mock_now = survivor->ready_at_tick;
        }

        launch_ready_jobs(mock_now);
        if (survivor->state != TC2_JOB_READY ||
            mock_positive_commands_by_train[14] !=
                    positive_before) {
                fprintf(stderr,
                        "prelaunch traffic gate did not hold T14 before "
                        "peer removal\n");
                return -1;
        }
        int cancel_status = cancel_job(15);
        if (cancel_status == 0) {
                mock_now = peer_runtime->settle_at_tick;
                process_braking_and_reversing(mock_now);
        }
        int remove_status =
                cancel_status == 0 &&
                        peer->state == TC2_JOB_STOPPED ?
                remove_job(15) : -1;
        int peer_after_remove = find_train_job(15);
        int peer_owner_after_remove =
                mock_reservations.owner_by_node[peer_node];
        if (remove_status < 0 ||
            peer_after_remove >= 0 ||
            peer_owner_after_remove != 0) {
                fprintf(stderr,
                        "prelaunch peer removal did not release T15 "
                        "cancel=%d remove=%d slot=%d node_owner=%d "
                        "state=%d\n",
                        cancel_status, remove_status,
                        peer_after_remove,
                        peer_owner_after_remove,
                        peer->state);
                return -1;
        }
        /* Removal alone must not bypass the next full safety pass. */
        launch_ready_jobs(mock_now);
        int remains_prelaunch_blocked =
                survivor->state == TC2_JOB_READY &&
                runtime->prelaunch_traffic_blocked;
        int rebuilding_authority =
                survivor->state == TC2_JOB_TRAFFIC_HOLD &&
                survivor->command_speed == 0 &&
                runtime->command_speed == 0 &&
                survivor->traffic_reason ==
                        TC2_TRAFFIC_AUTHORITY &&
                runtime->traffic_reason ==
                        TC2_TRAFFIC_AUTHORITY;
        if ((!remains_prelaunch_blocked &&
             !rebuilding_authority) ||
            mock_positive_commands_by_train[14] !=
                    positive_before) {
                fprintf(stderr,
                        "remove bypassed the prelaunch traffic recheck "
                        "state=%d gate=%d reason=%d/%d speed=%d/%d\n",
                        survivor->state,
                        runtime->prelaunch_traffic_blocked,
                        survivor->traffic_reason,
                        runtime->traffic_reason,
                        survivor->command_speed,
                        runtime->command_speed);
                return -1;
        }

        int resumed = 0;
        int release_tick = mock_now;
        for (int elapsed = 1;
             elapsed <= 200 && !resumed; ++elapsed) {
                int tick = tick_after(release_tick, elapsed);
                run_dispatch_server_tick_for_test(tick);
                resumed =
                        survivor->state == TC2_JOB_RUNNING &&
                        survivor->command_speed > 0;
        }
        if (!resumed ||
            mock_positive_commands_by_train[14] !=
                    positive_before + 1 ||
            mock_positive_commands_by_train[15] !=
                    peer_positive_before ||
            runtime->authority_resume_pending ||
            runtime->prelaunch_traffic_blocked ||
            survivor->plan_generation != generation_before ||
            survivor->target_node != destination_before ||
            survivor->destination_index !=
                    destination_index_before ||
            runtime->motion_anchor_distance_um < anchor_before ||
            !test_bytes_equal(
                    &runtime->route, &route_before,
                    sizeof(route_before))) {
                fprintf(stderr,
                        "remove15 did not restart blocked READY T14 "
                        "state=%d speed=%d positive=%d/%d gate=%d\n",
                        survivor->state, survivor->command_speed,
                        positive_before,
                        mock_positive_commands_by_train[14],
                        runtime->prelaunch_traffic_blocked);
                return -1;
        }
        return survivor_remains_running_after_remove(
                survivor_slot, 15, mock_now, 32,
                "READY authority remove/restart");
}

/*
 * Replay the missing state from field capture 19: the survivor is already
 * inside a FIFO-controlled turnout when pairwise HEAD_ON safety stops both
 * trains.  Removing the peer must retain the survivor's turnout ownership
 * and immediately resume under that CROSSING lock.  Rejecting every active
 * shared-turnout phase left the survivor permanently stopped with no later
 * state machine able to issue a positive speed command.
 */
static int check_crossing_survivor_resumes_after_remove(void) {
        int survivor_slot = -1;
        int peer_slot = -1;
        int peer_node = -1;
        if (setup_head_on_current_recovery_pair(
                    14, 15, &survivor_slot,
                    &peer_slot, &peer_node) < 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *survivor =
                &dispatch_jobs[survivor_slot];
        tc2_dispatch_runtime *survivor_runtime =
                &dispatch_runtime[survivor_slot];
        tc2_dispatch_job_snapshot *peer =
                &dispatch_jobs[peer_slot];
        tc2_dispatch_runtime *peer_runtime =
                &dispatch_runtime[peer_slot];

        const int switch_number = 5;
        const int direction = DIR_CURVED;
        int granted_direction = -1;
        if (Tc2TurnoutInterlockEnqueue(
                    &dispatch_turnout_interlocks,
                    switch_number, survivor->train,
                    direction) < 0 ||
            Tc2TurnoutInterlockGrantNext(
                    &dispatch_turnout_interlocks,
                    switch_number,
                    &granted_direction) !=
                    survivor->train ||
            granted_direction != direction ||
            Tc2TurnoutInterlockMarkSetting(
                    &dispatch_turnout_interlocks,
                    switch_number,
                    survivor->train) < 0 ||
            Tc2TurnoutInterlockMarkCrossing(
                    &dispatch_turnout_interlocks,
                    switch_number,
                    survivor->train) < 0) {
                return -1;
        }
        survivor_runtime->shared_turnout_phase =
                TC2_SHARED_TURNOUT_CROSSING;
        survivor_runtime->shared_turnout_switch =
                switch_number;
        survivor_runtime->shared_turnout_resource =
                Tc2TurnoutInterlockResourceForSwitch(
                        switch_number);
        survivor_runtime->shared_turnout_direction =
                direction;
        survivor_runtime->shared_turnout_route_offset =
                survivor->current_route_offset;
        survivor_runtime->shared_turnout_scalar_mm =
                survivor->confirmed_distance_mm;
        survivor_runtime->shared_turnout_hold_center_mm =
                survivor->confirmed_distance_mm;
        survivor_runtime->shared_turnout_resume_speed =
                survivor->speed;

        peer->state = TC2_JOB_TRAFFIC_HOLD;
        peer->command_speed = 0;
        peer->traffic_hold_active = 1;
        peer->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        peer->traffic_peer_train = survivor->train;
        peer->traffic_hold_distance_um = 0;
        peer_runtime->stop_purpose = TC2_STOP_TRAFFIC;
        peer_runtime->command_speed = 0;
        peer_runtime->motion_speed_ceiling = 20;
        peer_runtime->traffic_reason =
                TC2_TRAFFIC_HEAD_ON;
        peer_runtime->traffic_peer_train =
                survivor->train;
        peer_runtime->traffic_resume_speed = 20;
        peer_runtime->traffic_hold_distance_um = 0;

        if (cancel_job(peer->train) < 0) {
                return -1;
        }
        mock_now = peer_runtime->settle_at_tick;
        process_braking_and_reversing(mock_now);
        if (peer->state != TC2_JOB_STOPPED) {
                return -1;
        }
        int positive_before =
                mock_positive_speed_calls +
                mock_direct_positive_speed_calls;
        int peer_train = peer->train;
        if (remove_job(peer_train) < 0) {
                return -1;
        }
        int release_tick = mock_now;
        for (int elapsed = 1;
             elapsed <= 200 &&
                     survivor->state != TC2_JOB_RUNNING;
             ++elapsed) {
                int tick = tick_after(release_tick, elapsed);
                run_dispatch_server_tick_for_test(tick);
        }
        if (survivor->state != TC2_JOB_RUNNING ||
            survivor->command_speed <= 0 ||
            survivor_runtime->shared_turnout_phase !=
                    TC2_SHARED_TURNOUT_CROSSING ||
            Tc2TurnoutInterlockOwner(
                    &dispatch_turnout_interlocks,
                    switch_number) != survivor->train ||
            mock_positive_speed_calls +
                            mock_direct_positive_speed_calls <=
                    positive_before ||
            mock_reservations.owner_by_node[peer_node] != 0) {
                fprintf(stderr,
                        "capture19 crossing survivor did not resume "
                        "state=%d speed=%d phase=%d owner=%d "
                        "positive=%d/%d failure=%d reason=%d "
                        "authority=%d/%d conflict=%d:%d\n",
                        survivor->state,
                        survivor->command_speed,
                        survivor_runtime
                                ->shared_turnout_phase,
                        Tc2TurnoutInterlockOwner(
                                &dispatch_turnout_interlocks,
                                switch_number),
                        positive_before,
                        mock_positive_speed_calls +
                                mock_direct_positive_speed_calls,
                        survivor->failure_reason,
                        survivor_runtime->traffic_reason,
                        survivor_runtime->authority_end_offset,
                        survivor_runtime->route.node_count,
                        survivor->conflict_train,
                        survivor->conflict_node);
                return -1;
        }
        if (survivor_remains_running_after_remove(
                    survivor_slot, peer_train, mock_now, 32,
                    "shared-turnout CROSSING remove/restart") < 0 ||
            survivor_runtime->shared_turnout_phase !=
                    TC2_SHARED_TURNOUT_CROSSING ||
            Tc2TurnoutInterlockOwner(
                    &dispatch_turnout_interlocks,
                    switch_number) != survivor->train) {
                fprintf(stderr,
                        "CROSSING survivor lost its protected turnout "
                        "during post-remove observation phase=%d owner=%d\n",
                        survivor_runtime->shared_turnout_phase,
                        Tc2TurnoutInterlockOwner(
                                &dispatch_turnout_interlocks,
                                switch_number));
                return -1;
        }
        return 0;
}

/*
 * `cancel` proves only that a zero-speed command was accepted.  It is not
 * evidence that the train's body has cleared a FIFO-controlled turnout.
 * Exercise every phase in which the train already has a queue ticket or an
 * ownership claim.  The ticket/owner and the complete physical reservation
 * must survive both CANCEL_BRAKING and STOPPED; only operator `remove` may
 * release them.  A SETTING batch is also allowed to reach its terminal state
 * and mechanical settle, but a cancelled train must never resume or be
 * promoted to CROSSING as a side effect.
 */
static int check_cancel_keeps_shared_turnout_until_remove(void) {
        const int phases[] = {
                TC2_SHARED_TURNOUT_BRAKING,
                TC2_SHARED_TURNOUT_WAITING,
                TC2_SHARED_TURNOUT_SETTING,
                TC2_SHARED_TURNOUT_SETTLING,
                TC2_SHARED_TURNOUT_CROSSING
        };
        for (unsigned int phase_index = 0;
             phase_index < sizeof(phases) / sizeof(phases[0]);
             ++phase_index) {
                int survivor_slot = -1;
                int blocker_slot = -1;
                int blocker_node = -1;
                if (setup_head_on_current_recovery_pair(
                            14, 15, &survivor_slot,
                            &blocker_slot, &blocker_node) < 0) {
                        return -1;
                }
                (void)survivor_slot;
                tc2_dispatch_job_snapshot *blocker =
                        &dispatch_jobs[blocker_slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[blocker_slot];
                blocker->state = TC2_JOB_TRAFFIC_HOLD;
                blocker->command_speed = 0;
                blocker->hold_active = 1;
                blocker->traffic_hold_active = 1;
                blocker->traffic_reason = TC2_TRAFFIC_TURNOUT;
                blocker->traffic_peer_train = 0;
                blocker->traffic_hold_distance_um = 0;
                runtime->stop_purpose = TC2_STOP_TRAFFIC;
                runtime->command_speed = 0;
                runtime->motion_speed_ceiling = 20;
                runtime->motion_anchor_distance_um = 0;
                runtime->motion_anchor_tick = mock_now;
                runtime->motion_anchor_from_traffic = 1;
                runtime->traffic_reason = TC2_TRAFFIC_TURNOUT;
                runtime->traffic_peer_train = 0;
                runtime->traffic_resume_speed = 20;
                runtime->traffic_hold_distance_um = 0;
                runtime->shared_turnout_phase = phases[phase_index];
                runtime->shared_turnout_switch = 5;
                runtime->shared_turnout_resource =
                        Tc2TurnoutInterlockResourceForSwitch(5);
                runtime->shared_turnout_direction = DIR_CURVED;
                runtime->shared_turnout_route_offset = 0;
                runtime->shared_turnout_scalar_mm = 10000;
                runtime->shared_turnout_hold_center_mm = 9900;
                runtime->shared_turnout_resume_speed = 20;
                runtime->shared_turnout_batch_token = 0;
                runtime->shared_turnout_queue_pending = 0;
                runtime->shared_turnout_settle_at_tick = -1;

                if (Tc2TurnoutInterlockEnqueue(
                            &dispatch_turnout_interlocks,
                            5, 15, DIR_CURVED) < 0 ||
                    Tc2TurnoutInterlockEnqueue(
                            &dispatch_turnout_interlocks,
                            5, 17, DIR_STRAIGHT) < 0) {
                        return -1;
                }
                int direction = -1;
                int phase = phases[phase_index];
                if (phase == TC2_SHARED_TURNOUT_SETTING ||
                    phase == TC2_SHARED_TURNOUT_SETTLING ||
                    phase == TC2_SHARED_TURNOUT_CROSSING) {
                        if (Tc2TurnoutInterlockGrantNext(
                                    &dispatch_turnout_interlocks,
                                    5, &direction) != 15 ||
                            direction != DIR_CURVED ||
                            Tc2TurnoutInterlockMarkSetting(
                                    &dispatch_turnout_interlocks,
                                    5, 15) < 0) {
                                return -1;
                        }
                }
                if (phase == TC2_SHARED_TURNOUT_SETTING) {
                        mock_turnout_auto_complete = 0;
                        int token = queue_shared_turnout_action(
                                5, DIR_CURVED);
                        if (token <= 0) return -1;
                        runtime->shared_turnout_batch_token =
                                (unsigned int)token;
                } else if (phase ==
                           TC2_SHARED_TURNOUT_SETTLING) {
                        runtime->shared_turnout_settle_at_tick =
                                tick_after(mock_now, 2);
                } else if (phase ==
                           TC2_SHARED_TURNOUT_CROSSING) {
                        if (Tc2TurnoutInterlockMarkCrossing(
                                    &dispatch_turnout_interlocks,
                                    5, 15) < 0) {
                                return -1;
                        }
                }

                unsigned int generation =
                        mock_reservations.generation_by_train[15];
                unsigned char owned_before[TRACK_MAX];
                int owner_count = 0;
                for (int node = 0; node < TRACK_MAX; ++node) {
                        owned_before[node] =
                                mock_reservations.owner_by_node[node] ==
                                15;
                        owner_count += owned_before[node] ? 1 : 0;
                }
                int positive_before =
                        mock_positive_commands_by_train[15];
                if (generation == 0 || owner_count < 1 ||
                    mock_reservations.owner_by_node[blocker_node] != 15 ||
                    cancel_job(15) < 0) {
                        return -1;
                }

                run_dispatch_server_tick_for_test(mock_now);
                int waits_for_live_barrier =
                        phase == TC2_SHARED_TURNOUT_SETTING ||
                        phase == TC2_SHARED_TURNOUT_SETTLING;
                int expected_cancel_state =
                        waits_for_live_barrier ?
                        TC2_JOB_CANCEL_BRAKING :
                        TC2_JOB_STOPPED;
                if (blocker->state != expected_cancel_state ||
                    blocker->command_speed != 0 ||
                    mock_positive_commands_by_train[15] !=
                            positive_before) {
                        fprintf(stderr,
                                "cancelled shared-turnout train crossed its "
                                "barrier early/late phase=%d state=%d "
                                "expected=%d speed=%d\n",
                                phase, blocker->state,
                                expected_cancel_state,
                                blocker->command_speed);
                        return -1;
                }

                if (phase == TC2_SHARED_TURNOUT_SETTING) {
                        if (runtime->shared_turnout_batch_token == 0 ||
                            mock_turnout_status.state !=
                                    CAN_BATCH_PENDING) {
                                fprintf(stderr,
                                        "cancel discarded a live shared "
                                        "turnout batch\n");
                                return -1;
                        }
                        mock_turnout_status.state = CAN_BATCH_COMPLETE;
                        mock_turnout_status.confirmed =
                                mock_turnout_status.total;
                        run_dispatch_server_tick_for_test(
                                tick_after(mock_now, 1));
                        if (runtime->shared_turnout_phase !=
                                    TC2_SHARED_TURNOUT_SETTLING ||
                            runtime->shared_turnout_batch_token != 0) {
                                fprintf(stderr,
                                        "cancelled SETTING owner did not "
                                        "finish its terminal batch safely\n");
                                return -1;
                        }
                }
                if (runtime->shared_turnout_phase ==
                            TC2_SHARED_TURNOUT_SETTLING) {
                        int settle =
                                runtime->shared_turnout_settle_at_tick;
                        if (settle < 0) return -1;
                        run_dispatch_server_tick_for_test(settle);
                }

                if (blocker->state != TC2_JOB_STOPPED ||
                    blocker->command_speed != 0 ||
                    mock_positive_commands_by_train[15] !=
                            positive_before ||
                    mock_reservations.generation_by_train[15] !=
                            generation) {
                        fprintf(stderr,
                                "cancel released/resumed shared-turnout "
                                "train before remove phase=%d state=%d "
                                "speed=%d generation=%u/%u\n",
                                phase, blocker->state,
                                blocker->command_speed, generation,
                                mock_reservations
                                        .generation_by_train[15]);
                        return -1;
                }
                for (int node = 0; node < TRACK_MAX; ++node) {
                        if (owned_before[node] &&
                            mock_reservations.owner_by_node[node] != 15) {
                                fprintf(stderr,
                                        "cancel released %s before remove "
                                        "in shared phase %d\n",
                                        dispatch_track[node].name, phase);
                                return -1;
                        }
                }
                if (phase == TC2_SHARED_TURNOUT_BRAKING ||
                    phase == TC2_SHARED_TURNOUT_WAITING) {
                        if (!Tc2TurnoutInterlockIsQueued(
                                    &dispatch_turnout_interlocks,
                                    5, 15) ||
                            Tc2TurnoutInterlockOwner(
                                    &dispatch_turnout_interlocks,
                                    5) != 0) {
                                fprintf(stderr,
                                        "cancel lost pre-owner FIFO ticket "
                                        "phase=%d\n", phase);
                                return -1;
                        }
                } else if (Tc2TurnoutInterlockOwner(
                                   &dispatch_turnout_interlocks,
                                   5) != 15 ||
                           (phase != TC2_SHARED_TURNOUT_CROSSING &&
                            runtime->shared_turnout_phase ==
                                    TC2_SHARED_TURNOUT_CROSSING)) {
                        fprintf(stderr,
                                "cancel lost owner or promoted cancelled "
                                "train to CROSSING phase=%d runtime=%d "
                                "owner=%d\n",
                                phase,
                                runtime->shared_turnout_phase,
                                Tc2TurnoutInterlockOwner(
                                        &dispatch_turnout_interlocks,
                                        5));
                        return -1;
                }

                int remove_status = remove_job(15);
                int owner_after_remove =
                        Tc2TurnoutInterlockOwner(
                                &dispatch_turnout_interlocks, 5);
                int next_after_remove =
                        Tc2TurnoutInterlockGrantNext(
                                &dispatch_turnout_interlocks,
                                5, &direction);
                if (remove_status < 0 ||
                    mock_reservations.owner_by_node[blocker_node] != 0 ||
                    Tc2TurnoutInterlockIsQueued(
                            &dispatch_turnout_interlocks, 5, 15) ||
                    owner_after_remove != 0 ||
                    next_after_remove != 17 ||
                    direction != DIR_STRAIGHT) {
                        fprintf(stderr,
                                "remove did not release shared phase %d "
                                "to the next FIFO train status=%d owner=%d "
                                "next=%d direction=%d queued15=%d "
                                "generation=%u node_owner=%d\n",
                                phase, remove_status,
                                owner_after_remove,
                                next_after_remove, direction,
                                Tc2TurnoutInterlockIsQueued(
                                        &dispatch_turnout_interlocks,
                                        5, 15),
                                mock_reservations
                                        .generation_by_train[15],
                                mock_reservations
                                        .owner_by_node[blocker_node]);
                        return -1;
                }
        }
        return 0;
}

static int install_stopped_same_route_peer(
        int source_slot, int train, int position_mm,
        int *peer_slot_out, int *reserved_node_out) {
        if (source_slot < 0 ||
            source_slot >= TC2_DISPATCH_MAX_JOBS ||
            train < 1 || train > 255 || position_mm < 0 ||
            !peer_slot_out || !reserved_node_out) {
                return -1;
        }
        int reserved_node = -1;
        for (int node = 0; node < TRACK_MAX; ++node) {
                int reverse = physical_reverse_index(node);
                if (mock_reservations.owner_by_node[node] == 0 &&
                    (reverse < 0 ||
                     mock_reservations.owner_by_node[reverse] == 0)) {
                        reserved_node = node;
                        break;
                }
        }
        int peer_slot = find_empty_job();
        if (reserved_node < 0 || peer_slot < 0) return -1;
        track_route hold = {0};
        hold.node_count = 1;
        hold.nodes[0] = reserved_node;
        track_reservation_conflict conflict;
        unsigned int generation = 0;
        if (TrackReservationTryWindowToGeneration(
                    &mock_reservations, dispatch_track,
                    &hold, train, reserved_node,
                    &conflict, &generation) != 0 ||
            generation == 0) {
                return -1;
        }
        dispatch_jobs[peer_slot] =
                dispatch_jobs[source_slot];
        dispatch_runtime[peer_slot] =
                dispatch_runtime[source_slot];
        tc2_dispatch_job_snapshot *peer =
                &dispatch_jobs[peer_slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[peer_slot];
        peer->train = train;
        peer->state = TC2_JOB_STOPPED;
        peer->command_speed = 0;
        peer->plan_generation = generation;
        peer->target_node = reserved_node;
        peer->hold_active = 1;
        peer->traffic_hold_active = 1;
        peer->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        peer->traffic_peer_train = 0;
        peer->estimated_distance_um =
                (int64_t)position_mm * 1000;
        peer->traffic_hold_distance_um =
                (int64_t)position_mm * 1000;
        runtime->command_speed = 0;
        runtime->motion_speed_ceiling = 0;
        runtime->motion_anchor_distance_um =
                (int64_t)position_mm * 1000;
        runtime->motion_anchor_tick = mock_now;
        runtime->motion_anchor_from_traffic = 1;
        runtime->monitor.confirmed_distance_mm =
                position_mm;
        runtime->stop_purpose = TC2_STOP_TRAFFIC;
        runtime->settle_at_tick = -1;
        runtime->traffic_reason = TC2_TRAFFIC_HEAD_ON;
        runtime->traffic_peer_train = 0;
        runtime->traffic_resume_speed = 20;
        runtime->traffic_hold_distance_um =
                (int64_t)position_mm * 1000;
        runtime->authority_resume_pending = 0;
        runtime->prelaunch_traffic_blocked = 0;
        clear_shared_turnout_runtime(runtime);
        *peer_slot_out = peer_slot;
        *reserved_node_out = reserved_node;
        return 0;
}

/*
 * A released peer is only one scheduling event; it is not proof that a
 * stopped train's corridor is clear.  Populate all four managed slots with
 * one survivor and three independent STOPPED blockers at the same route
 * position.  Removing either of the first two blockers must leave the
 * survivor stopped with no positive CAN command.  Only after the last
 * blocker is removed may the ordinary all-pairs/authority pass resume it.
 *
 * Train numbers are data in one indexed fixture.  No assertion or release
 * path is specialized for a particular 14/15 pairing.
 */
static int check_four_train_multi_blocker_requires_all_clear(void) {
        enum {
                PHYSICAL_FLEET_SIZE = 4,
                SURVIVOR_INDEX = 0,
                FIRST_BLOCKER_INDEX = 1
        };
        static const int trains[PHYSICAL_FLEET_SIZE] = {
                18, 17, 15, 14
        };
        const int blocker_count =
                PHYSICAL_FLEET_SIZE - FIRST_BLOCKER_INDEX;
        reset_dispatch_test();
        if (prepare_one_trip(
                    trains[SURVIVOR_INDEX], 0, 0, 20) != 0) {
                return -1;
        }
        int survivor_slot =
                find_train_job(trains[SURVIVOR_INDEX]);
        if (survivor_slot < 0) return -1;
        mock_now = dispatch_jobs[survivor_slot].ready_at_tick;
        launch_ready_jobs(mock_now);
        process_launching_jobs(mock_now);
        tc2_dispatch_job_snapshot *survivor =
                &dispatch_jobs[survivor_slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[survivor_slot];
        if (survivor->state != TC2_JOB_RUNNING) return -1;
        runtime->rolling_authority_active = 1;
        runtime->authority_end_offset =
                runtime->route.node_count - 1;
        runtime->authority_center_ceiling_mm =
                survivor->destination_distance_mm;

        int survivor_mm = 200;
        int uncertainty = Tc2MotionUncertaintyMm(20);
        int blocker_mm =
                survivor_mm + uncertainty +
                TC2_TRAIN_BODY_MM +
                TC2_TRAFFIC_FOLLOWING_STOP_DISTANCE_MM;
        if (uncertainty < 0 ||
            blocker_mm >= survivor->destination_distance_mm) {
                return -1;
        }
        survivor->state = TC2_JOB_TRAFFIC_HOLD;
        survivor->command_speed = 0;
        survivor->hold_active = 1;
        survivor->traffic_hold_active = 1;
        survivor->traffic_reason = TC2_TRAFFIC_FOLLOWING;
        survivor->traffic_peer_train =
                trains[FIRST_BLOCKER_INDEX];
        survivor->traffic_hold_distance_um =
                (int64_t)survivor_mm * 1000;
        survivor->estimated_distance_um =
                (int64_t)survivor_mm * 1000;
        runtime->command_speed = 0;
        runtime->motion_speed_ceiling = 20;
        runtime->motion_anchor_distance_um =
                (int64_t)survivor_mm * 1000;
        runtime->motion_anchor_tick = mock_now;
        runtime->motion_anchor_from_traffic = 1;
        runtime->monitor.confirmed_distance_mm = survivor_mm;
        runtime->stop_purpose = TC2_STOP_TRAFFIC;
        runtime->traffic_reason = TC2_TRAFFIC_FOLLOWING;
        runtime->traffic_peer_train =
                trains[FIRST_BLOCKER_INDEX];
        runtime->traffic_resume_speed = 20;
        runtime->traffic_hold_distance_um =
                (int64_t)survivor_mm * 1000;
        runtime->traffic_hold_since_tick = mock_now;

        int blocker_slots[PHYSICAL_FLEET_SIZE - 1];
        int blocker_nodes[PHYSICAL_FLEET_SIZE - 1];
        for (int blocker = 0;
             blocker < blocker_count; ++blocker) {
                blocker_slots[blocker] = -1;
                blocker_nodes[blocker] = -1;
                int train_index =
                        FIRST_BLOCKER_INDEX + blocker;
                if (install_stopped_same_route_peer(
                            survivor_slot,
                            trains[train_index], blocker_mm,
                            &blocker_slots[blocker],
                            &blocker_nodes[blocker]) < 0) {
                        return -1;
                }
                tc2_live_traffic_relation relation;
                if (live_traffic_relation_for_pair(
                            survivor_slot,
                            blocker_slots[blocker], mock_now,
                            &relation) < 0 ||
                    !relation.valid ||
                    relation.rear_slot != survivor_slot ||
                    relation.gap_mm >
                            TC2_TRAFFIC_FOLLOWING_STOP_DISTANCE_MM) {
                        fprintf(stderr,
                                "four-train fixture blocker[%d]=T%d "
                                "was not a live physical blocker gap=%d "
                                "relation=%d rear=%d/%d\n",
                                blocker, trains[train_index],
                                relation.gap_mm,
                                relation.relation,
                                relation.rear_slot, survivor_slot);
                        return -1;
                }
        }

        int positive_before =
                mock_positive_commands_by_train[
                        trains[SURVIVOR_INDEX]];
        for (int removed = 0;
             removed < blocker_count; ++removed) {
                int train_index =
                        FIRST_BLOCKER_INDEX + removed;
                int blocker_train = trains[train_index];
                if (cancel_job(blocker_train) < 0) return -1;
                process_braking_and_reversing(mock_now);
                if (dispatch_jobs[blocker_slots[removed]].state !=
                            TC2_JOB_STOPPED ||
                    remove_job(blocker_train) < 0 ||
                    find_train_job(blocker_train) >= 0 ||
                    mock_reservations.owner_by_node[
                            blocker_nodes[removed]] != 0 ||
                    mock_positive_commands_by_train[
                            trains[SURVIVOR_INDEX]] !=
                            positive_before) {
                        return -1;
                }
                if (removed == blocker_count - 1) break;

                int release_tick = mock_now;
                for (int elapsed = 1;
                     elapsed <= 64; ++elapsed) {
                        run_dispatch_server_tick_for_test(
                                tick_after(release_tick,
                                           elapsed));
                        if (mock_positive_commands_by_train[
                                    trains[SURVIVOR_INDEX]] !=
                                            positive_before ||
                            survivor->state == TC2_JOB_RUNNING ||
                            survivor->state == TC2_JOB_FAILED) {
                                fprintf(stderr,
                                        "removing blocker[%d]=T%d "
                                        "bypassed another live blocker "
                                        "elapsed=%d state=%d speed=%d "
                                        "positive=%d/%d reason=%d peer=%d\n",
                                        removed, blocker_train,
                                        elapsed, survivor->state,
                                        survivor->command_speed,
                                        positive_before,
                                        mock_positive_commands_by_train[
                                                trains[
                                                SURVIVOR_INDEX]],
                                        runtime->traffic_reason,
                                        runtime->traffic_peer_train);
                                return -1;
                        }
                        for (int remaining = removed + 1;
                             remaining < blocker_count;
                             ++remaining) {
                                int remaining_train =
                                        trains[
                                                FIRST_BLOCKER_INDEX +
                                                remaining];
                                if (find_train_job(remaining_train) !=
                                            blocker_slots[remaining] ||
                                    mock_reservations.owner_by_node[
                                            blocker_nodes[remaining]] !=
                                            remaining_train) {
                                        return -1;
                                }
                        }
                }
        }

        int final_release_tick = mock_now;
        int resumed = 0;
        for (int elapsed = 1; elapsed <= 400; ++elapsed) {
                run_dispatch_server_tick_for_test(
                        tick_after(final_release_tick, elapsed));
                if (survivor->state == TC2_JOB_FAILED) {
                        break;
                }
                if (survivor->state == TC2_JOB_RUNNING &&
                    survivor->command_speed > 0 &&
                    mock_positive_commands_by_train[
                            trains[SURVIVOR_INDEX]] >
                            positive_before) {
                        resumed = 1;
                        break;
                }
        }
        if (!resumed ||
            runtime->authority_rebuild_after_release ||
            runtime->prelaunch_traffic_blocked) {
                fprintf(stderr,
                        "final peer removal did not complete fresh "
                        "authority/all-pairs recovery state=%d speed=%d "
                        "positive=%d/%d reason=%d rebuild=%d gate=%d\n",
                        survivor->state, survivor->command_speed,
                        positive_before,
                        mock_positive_commands_by_train[
                                trains[SURVIVOR_INDEX]],
                        runtime->traffic_reason,
                        runtime->authority_rebuild_after_release,
                        runtime->prelaunch_traffic_blocked);
                return -1;
        }
        return 0;
}

static int check_exact_current_all_pairs_and_leading_reversal(void) {
        int leading_reversals = 0;
        int zero_distance_leading = 0;
        int zero_distance_turnout_batches = 0;
        int zero_distance_same_target_batches = 0;
        int localization_chains = 0;
        for (int old_destination = 0;
             old_destination <
                     TC2_DISPATCH_DESTINATION_COUNT;
             ++old_destination) {
                for (int old_side = 0;
                     old_side < 2; ++old_side) {
                        const char *old_name =
                                old_side == 0 ?
                                Tc2DispatchDestinationSensorA(
                                        old_destination) :
                                Tc2DispatchDestinationSensorB(
                                        old_destination);
                        int old_node =
                                TrackFindNodeByName(
                                        dispatch_track, old_name);
                        for (int new_destination = 0;
                             new_destination <
                                     TC2_DISPATCH_DESTINATION_COUNT;
                             ++new_destination) {
                                reset_dispatch_test();
                                old_node =
                                        TrackFindNodeByName(
                                                dispatch_track,
                                                old_name);
                                if (force_exact_directed_hold(
                                            121, old_node, 50) < 0) {
                                        fprintf(stderr,
                                                "exact CURRENT could not "
                                                "create hold at %s\n",
                                                old_name);
                                        return -1;
                                }
                                int slot = find_train_job(121);
                                unsigned int old_generation =
                                        dispatch_jobs[slot]
                                                .plan_generation;
                                tc2_dispatch_request current;
                                clear_request(
                                        &current,
                                        TC2_DISPATCH_MSG_STAGE);
                                current.train = 121;
                                current.start_index =
                                        TC2_DISPATCH_START_CURRENT;
                                current.speed =
                                        new_destination ==
                                                old_destination ?
                                        120 : 50;
                                current.destination_index =
                                        new_destination;
                                if (stage_job(&current) < 0) {
                                        track_route diagnostic_carry;
                                        track_turnout_plan diagnostic_turnouts;
                                        int diagnostic =
                                                build_stationary_current_carry_ambiguity(
                                                        slot,
                                                        &diagnostic_carry,
                                                        &diagnostic_turnouts);
                                        fprintf(stderr,
                                                "exact CURRENT pair "
                                                "%s->D%d could not stage "
                                                "carry=%d route=%d current=%d "
                                                "node=%s state=%d estimated=%d "
                                                "purpose=%d distance=%d\n",
                                                old_name,
                                                new_destination + 1,
                                                diagnostic,
                                                dispatch_runtime[slot]
                                                        .route_valid,
                                                dispatch_jobs[slot]
                                                        .current_route_offset,
                                                dispatch_jobs[slot]
                                                                .current_node >=
                                                        0 ?
                                                        dispatch_track[
                                                                dispatch_jobs[
                                                                        slot]
                                                                        .current_node]
                                                                .name :
                                                        "none",
                                                dispatch_jobs[slot].state,
                                                dispatch_jobs[slot]
                                                        .position_estimated,
                                                dispatch_runtime[slot]
                                                        .stop_purpose,
                                                dispatch_jobs[slot]
                                                        .destination_distance_mm);
                                        return -1;
                                }
                                dispatch_jobs[slot].state =
                                        TC2_JOB_WAITING;
                                dispatch_jobs[slot].queue_sequence =
                                        ++dispatch_queue_sequence;
                                dispatch_jobs[slot]
                                        .job_launch_epoch = 1;
                                dispatch_runtime[slot]
                                        .queue_sequence =
                                        dispatch_jobs[slot]
                                                .queue_sequence;
                                dispatch_runtime[slot]
                                        .wait_since_tick = mock_now;
                                dispatch_runtime[slot]
                                        .launch_epoch = 1;
                                mock_reverse_confirmation_tick_advance =
                                        3;
                                int prepare_status =
                                        prepare_waiting_job(
                                                slot, mock_now);
                                if (prepare_status != 0) {
                                        fprintf(stderr,
                                                "exact CURRENT pair "
                                                "%s->D%d did not plan "
                                                "status=%d state=%d "
                                                "conflict=%d/%d\n",
                                                old_name,
                                                new_destination + 1,
                                                prepare_status,
                                                dispatch_jobs[slot].state,
                                                dispatch_jobs[slot]
                                                        .conflict_train,
                                                dispatch_jobs[slot]
                                                        .conflict_node);
                                        return -1;
                                }
                                tc2_dispatch_job_snapshot *job =
                                        &dispatch_jobs[slot];
                                tc2_dispatch_runtime *runtime =
                                        &dispatch_runtime[slot];
                                if (route_has_consecutive_reversals(
                                            &runtime->route,
                                            job
                                                    ->target_route_offset)) {
                                        fprintf(stderr,
                                                "exact CURRENT pair "
                                                "%s->D%d retained "
                                                "consecutive zero-distance "
                                                "reversals\n",
                                                old_name,
                                                new_destination + 1);
                                        return -1;
                                }
                                int leading =
                                        runtime->route.node_count > 1 &&
                                        dispatch_track[
                                                runtime->route.nodes[0]]
                                                        .reverse ==
                                                &dispatch_track[
                                                        runtime
                                                                ->route
                                                                .nodes[1]];
                                if (leading) {
                                        ++leading_reversals;
                                        if (mock_reverse_calls != 0 ||
                                            !runtime
                                                     ->prelaunch_reverse_pending ||
                                            job->reversals_completed != 1 ||
                                            job->current_leg != 1 ||
                                            runtime->leg_start_offset != 1 ||
                                            mock_positive_speed_calls != 0 ||
                                            job->plan_generation ==
                                                    old_generation) {
                                                fprintf(stderr,
                                                        "leading reversal "
                                                        "%s->D%d was not "
                                                        "held pending while "
                                                        "stopped\n",
                                                        old_name,
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        if (runtime
                                                    ->turnout_batch_token !=
                                            0) {
                                                ++zero_distance_turnout_batches;
                                                mock_turnout_status.state =
                                                        CAN_BATCH_COMPLETE;
                                                mock_turnout_status
                                                        .confirmed =
                                                        mock_turnout_status
                                                                .total;
                                                process_preparing_jobs(
                                                        mock_now);
                                        }
                                        int turnout_settle =
                                                runtime
                                                        ->prelaunch_turnout_settle_at_tick;
                                        if (turnout_settle < 0 ||
                                            mock_reverse_calls != 0) {
                                                fprintf(stderr,
                                                        "leading reversal "
                                                        "%s->D%d bypassed "
                                                        "turnout "
                                                        "confirmation\n",
                                                        old_name,
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        if (turnout_settle > mock_now) {
                                                mock_now =
                                                        turnout_settle - 1;
                                                process_preparing_jobs(
                                                        mock_now);
                                                if (mock_reverse_calls != 0 ||
                                                    job->state !=
                                                            TC2_JOB_PREPARING) {
                                                        fprintf(stderr,
                                                                "leading "
                                                                "reversal "
                                                                "%s->D%d ran "
                                                                "before "
                                                                "turnout "
                                                                "settle "
                                                                "calls=%d "
                                                                "state=%d "
                                                                "failure=%d "
                                                                "now=%d "
                                                                "settle=%d\n",
                                                                old_name,
                                                                new_destination +
                                                                        1,
                                                                mock_reverse_calls,
                                                                job->state,
                                                                job->failure_reason,
                                                                mock_now,
                                                                turnout_settle);
                                                        return -1;
                                                }
                                        }
                                        mock_now = turnout_settle;
                                        process_preparing_jobs(mock_now);
                                        int reverse_ready =
                                                runtime
                                                        ->prelaunch_reverse_ready_at_tick;
                                        if (mock_reverse_calls != 1 ||
                                            runtime
                                                    ->prelaunch_reverse_pending ||
                                            mock_last_reverse_order == 0 ||
                                            reverse_ready < 0 ||
                                            job->state !=
                                                    TC2_JOB_PREPARING) {
                                                fprintf(stderr,
                                                        "leading reversal "
                                                        "%s->D%d did not "
                                                        "enter direction "
                                                        "settle calls=%d "
                                                        "pending=%d order=%d "
                                                        "ready=%d state=%d "
                                                        "turnout=%u settle=%d "
                                                        "now=%d\n",
                                                        old_name,
                                                        new_destination + 1,
                                                        mock_reverse_calls,
                                                        runtime
                                                                ->prelaunch_reverse_pending,
                                                        mock_last_reverse_order,
                                                        reverse_ready,
                                                        job->state,
                                                        runtime
                                                                ->turnout_batch_token,
                                                        turnout_settle,
                                                        mock_now);
                                                return -1;
                                        }
                                        if (job->route_distance_mm == 0 &&
                                            runtime->leg_start_offset ==
                                                    job
                                                            ->target_route_offset) {
                                                ++zero_distance_leading;
                                                mock_now = reverse_ready - 1;
                                                process_preparing_jobs(
                                                        mock_now);
                                                if (job->state !=
                                                            TC2_JOB_PREPARING ||
                                                    mock_reverse_calls != 1 ||
                                                    mock_speed_batch_calls !=
                                                            0) {
                                                        fprintf(stderr,
                                                                "zero-distance "
                                                                "leading "
                                                                "reversal "
                                                                "arrived "
                                                                "before "
                                                                "settle\n");
                                                        return -1;
                                                }
                                                mock_now = reverse_ready;
                                                process_preparing_jobs(
                                                        mock_now);
                                                if (job->state !=
                                                            TC2_JOB_ARRIVED ||
                                                    runtime
                                                            ->zero_motion_arrival_pending ||
                                                    mock_speed_batch_calls !=
                                                            0) {
                                                        fprintf(stderr,
                                                                "zero-distance "
                                                                "leading "
                                                                "reversal "
                                                                "did not "
                                                                "arrive "
                                                                "after "
                                                                "settle\n");
                                                        return -1;
                                                }
                                                continue;
                                        }
                                        mock_now = reverse_ready;
                                } else if (mock_reverse_calls != 0) {
                                        fprintf(stderr,
                                                "non-leading exact CURRENT "
                                                "%s->D%d issued %d reverse "
                                                "commands\n",
                                                old_name,
                                                new_destination + 1,
                                                mock_reverse_calls);
                                        return -1;
                                }
                                if (runtime
                                            ->zero_motion_arrival_pending) {
                                        if (leading ||
                                            job->route_distance_mm != 0 ||
                                            runtime
                                                    ->leg_start_offset !=
                                                    job
                                                            ->target_route_offset ||
                                            job->state !=
                                                    TC2_JOB_PREPARING ||
                                            mock_speed_batch_calls != 0) {
                                                fprintf(stderr,
                                                        "same-target "
                                                        "CURRENT %s->D%d "
                                                        "entered an invalid "
                                                        "zero-motion state\n",
                                                        old_name,
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        mock_now =
                                                runtime
                                                        ->zero_motion_arrival_ready_at_tick;
                                        if (runtime
                                                    ->turnout_batch_token !=
                                            0) {
                                                ++zero_distance_same_target_batches;
                                                mock_turnout_status.state =
                                                        CAN_BATCH_PENDING;
                                                mock_turnout_status
                                                        .confirmed = 0;
                                                process_preparing_jobs(
                                                        mock_now);
                                                tc2_dispatch_request
                                                        premature;
                                                clear_request(
                                                        &premature,
                                                        TC2_DISPATCH_MSG_STAGE);
                                                premature.train =
                                                        job->train;
                                                premature.start_index =
                                                        TC2_DISPATCH_START_CURRENT;
                                                premature.speed =
                                                        job->speed;
                                                premature
                                                        .destination_index =
                                                        (new_destination +
                                                         1) %
                                                        TC2_DISPATCH_DESTINATION_COUNT;
                                                if (job->state !=
                                                            TC2_JOB_PREPARING ||
                                                    stage_job(
                                                            &premature) ==
                                                            0) {
                                                        fprintf(stderr,
                                                                "same-target "
                                                                "CURRENT "
                                                                "published an "
                                                                "unconfirmed "
                                                                "turnout plan\n");
                                                        return -1;
                                                }
                                                mock_turnout_status.state =
                                                        CAN_BATCH_COMPLETE;
                                                mock_turnout_status
                                                        .confirmed =
                                                        mock_turnout_status
                                                                .total;
                                        }
                                        process_preparing_jobs(mock_now);
                                        if (job->state !=
                                                    TC2_JOB_ARRIVED ||
                                            runtime
                                                    ->zero_motion_arrival_pending ||
                                            mock_speed_batch_calls != 0) {
                                                fprintf(stderr,
                                                        "same-target "
                                                        "CURRENT %s->D%d "
                                                        "did not finish its "
                                                        "zero-motion "
                                                        "barrier\n",
                                                        old_name,
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        continue;
                                }
                                if (job->state ==
                                            TC2_JOB_PREPARING &&
                                    !runtime
                                             ->zero_motion_arrival_pending &&
                                    runtime->leg_start_offset <
                                            job
                                                    ->target_route_offset &&
                                    runtime->leg_end_offset <=
                                            runtime
                                                    ->leg_start_offset) {
                                        fprintf(stderr,
                                                "exact CURRENT pair "
                                                "%s->D%d prepared a "
                                                "zero-motion launch leg\n",
                                                old_name,
                                                new_destination + 1);
                                        return -1;
                                }
                                if (runtime->localization_only) {
                                        int reached_requested_route = 0;
                                        for (int hop = 0;
                                             hop <
                                                     TC2_MAX_LOCALIZATION_HOPS;
                                             ++hop) {
                                                process_preparing_jobs(
                                                        mock_now);
                                                if (job->state !=
                                                    TC2_JOB_READY) {
                                                        fprintf(stderr,
                                                                "clearance "
                                                                "%s->D%d "
                                                                "failed to "
                                                                "become READY "
                                                                "state=%d "
                                                                "hop=%d\n",
                                                                old_name,
                                                                new_destination + 1,
                                                                job->state,
                                                                hop);
                                                        return -1;
                                                }
                                                int prior_sensor =
                                                        runtime
                                                                ->leg_start_offset;
                                                for (int offset =
                                                             runtime
                                                                     ->leg_start_offset;
                                                     offset <
                                                             job
                                                                     ->target_route_offset;
                                                     ++offset) {
                                                        if (dispatch_track[
                                                                    runtime
                                                                            ->route
                                                                            .nodes[
                                                                                    offset]]
                                                                    .type ==
                                                            NODE_SENSOR) {
                                                                prior_sensor =
                                                                        offset;
                                                        }
                                                }
                                                job->state =
                                                        TC2_JOB_BRAKING;
                                                job->current_route_offset =
                                                        job
                                                                ->target_route_offset;
                                                job->current_node =
                                                        job->target_node;
                                                runtime
                                                        ->reservation_anchor_offset =
                                                        prior_sensor;
                                                runtime->target_seen = 1;
                                                /*
                                                 * Consume at most one
                                                 * uncorroborated clearance
                                                 * target in this sweep.
                                                 * Later phases model the
                                                 * ordered evidence available
                                                 * under TC2's single-error
                                                 * budget.
                                                 */
                                                runtime
                                                        ->target_corroborated =
                                                        hop > 0;
                                                runtime->stop_purpose =
                                                        TC2_STOP_DESTINATION;
                                                runtime->settle_at_tick =
                                                        mock_now;
                                                if (update_remaining_footprint(
                                                            slot) < 0) {
                                                        fprintf(stderr,
                                                                "clearance "
                                                                "%s->D%d "
                                                                "could not "
                                                                "slide hold "
                                                                "at hop=%d\n",
                                                                old_name,
                                                                new_destination + 1,
                                                                hop);
                                                        return -1;
                                                }
                                                process_braking_and_reversing(
                                                        mock_now);
                                                if (job->state !=
                                                            TC2_JOB_WAITING ||
                                                    job
                                                            ->destination_index !=
                                                            new_destination) {
                                                        fprintf(stderr,
                                                                "clearance "
                                                                "%s->D%d "
                                                                "did not "
                                                                "restage at "
                                                                "hop=%d "
                                                                "state=%d "
                                                                "dest=%d\n",
                                                                old_name,
                                                                new_destination + 1,
                                                                hop,
                                                                job->state,
                                                                job
                                                                        ->destination_index);
                                                        return -1;
                                                }
                                                int next_prepare =
                                                        prepare_waiting_job(
                                                                slot,
                                                                mock_now);
                                                if (next_prepare != 0) {
                                                        fprintf(stderr,
                                                                "clearance "
                                                                "%s->D%d "
                                                                "could not "
                                                                "prepare hop "
                                                                "%d status=%d "
                                                                "state=%d\n",
                                                                old_name,
                                                                new_destination + 1,
                                                                hop + 1,
                                                                next_prepare,
                                                                job->state);
                                                        fprintf(stderr,
                                                                "  start=%s "
                                                                "estimated=%d "
                                                                "carry=%d "
                                                                "generation=%u "
                                                                "hops=%d\n",
                                                                dispatch_track[
                                                                        dispatch_runtime[
                                                                                slot]
                                                                                .start_node]
                                                                        .name,
                                                                dispatch_runtime[
                                                                        slot]
                                                                        .carry_position_estimated,
                                                                dispatch_runtime[
                                                                        slot]
                                                                        .carry_ambiguity_active,
                                                                job
                                                                        ->plan_generation,
                                                                dispatch_runtime[
                                                                        slot]
                                                                        .localization_hops);
                                                        return -1;
                                                }
                                                job =
                                                        &dispatch_jobs[slot];
                                                runtime =
                                                        &dispatch_runtime[
                                                                slot];
                                                if (!runtime
                                                             ->localization_only) {
                                                        int side_a =
                                                                TrackFindNodeByName(
                                                                        dispatch_track,
                                                                        Tc2DispatchDestinationSensorA(
                                                                                new_destination));
                                                        int side_b =
                                                                TrackFindNodeByName(
                                                                        dispatch_track,
                                                                        Tc2DispatchDestinationSensorB(
                                                                                new_destination));
                                                        if (job->target_node !=
                                                                    side_a &&
                                                            job->target_node !=
                                                                    side_b) {
                                                                fprintf(stderr,
                                                                        "clearance "
                                                                        "%s->D%d "
                                                                        "ended "
                                                                        "at "
                                                                        "non-D "
                                                                        "node "
                                                                        "%d\n",
                                                                        old_name,
                                                                        new_destination + 1,
                                                                        job
                                                                                ->target_node);
                                                                return -1;
                                                        }
                                                        reached_requested_route =
                                                                1;
                                                        break;
                                                }
                                        }
                                        if (!reached_requested_route) {
                                                fprintf(stderr,
                                                        "exact CURRENT "
                                                        "clearance chain "
                                                        "%s->D%d did not "
                                                        "converge\n",
                                                        old_name,
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        ++localization_chains;
                                        continue;
                                }
                                if (job->state == TC2_JOB_ARRIVED) {
                                        continue;
                                }
                                if (job->state !=
                                    TC2_JOB_PREPARING) {
                                        fprintf(stderr,
                                                "exact CURRENT %s->D%d "
                                                "unexpected prelaunch "
                                                "state=%d\n",
                                                old_name,
                                                new_destination + 1,
                                                job->state);
                                        return -1;
                                }
                                process_preparing_jobs(mock_now);
                                if (job->state != TC2_JOB_READY ||
                                    (leading &&
                                     !tick_reached(
                                             job->ready_at_tick,
                                             runtime
                                                     ->prelaunch_reverse_ready_at_tick))) {
                                        fprintf(stderr,
                                                "exact CURRENT %s->D%d "
                                                "failed READY barrier "
                                                "state=%d ready=%d "
                                                "reverse_ready=%d\n",
                                                old_name,
                                                new_destination + 1,
                                                job->state,
                                                job->ready_at_tick,
                                                runtime
                                                        ->prelaunch_reverse_ready_at_tick);
                                        return -1;
                                }
                                mock_now = job->ready_at_tick;
                                launch_ready_jobs(mock_now);
                                if (job->state !=
                                            TC2_JOB_LAUNCHING ||
                                    mock_speed_batch_calls != 1 ||
                                    mock_positive_speed_calls != 1 ||
                                    (leading &&
                                     mock_first_positive_order <=
                                             mock_last_reverse_order)) {
                                        fprintf(stderr,
                                                "exact CURRENT %s->D%d "
                                                "failed launch state=%d "
                                                "batches=%d positive=%d "
                                                "orders=%d/%d\n",
                                                old_name,
                                                new_destination + 1,
                                                job->state,
                                                mock_speed_batch_calls,
                                                mock_positive_speed_calls,
                                                mock_last_reverse_order,
                                                mock_first_positive_order);
                                        return -1;
                                }
                        }
                }
        }
        /*
         * ARRIVED CURRENT now carries only the stationary body corridor.
         * Exact positions therefore no longer need a synthetic clearance
         * chain and the optimizer is not required to choose a leading
         * reversal.  Dedicated capture40 and constructed barrier tests cover
         * those two mechanisms; this sweep still validates every exact
         * source/destination pair and its zero-motion publication barrier.
         */
        if (zero_distance_same_target_batches == 0) {
                fprintf(stderr,
                        "exact CURRENT sweep lacked zero-motion "
                        "turnout confirmation coverage "
                        "(leading=%d zero-leading=%d leading-batch=%d "
                        "same-target-batch=%d clearance=%d)\n",
                        leading_reversals,
                        zero_distance_leading,
                        zero_distance_turnout_batches,
                        zero_distance_same_target_batches,
                        localization_chains);
                return -1;
        }
        return 0;
}

static int check_estimated_current_relocalization(void) {
        int chosen_slot = -1;
        int first_destination = -1;
        int second_destination = -1;
        tc2_route_sensor_point first;
        tc2_route_sensor_point second;
        tc2_route_sensor_point third;
        tc2_route_sensor_point fourth;
        int carry_only_node = -1;
        unsigned int old_generation = 0;
        int old_destination_node = -1;
        int staged_candidates = 0;
        int prepared_candidates = 0;
        int sensor_candidates = 0;
        int carry_candidates = 0;
        int held_candidates = 0;
        int current_stage_successes = 0;

        for (int old_destination = 0;
             old_destination <
                     TC2_DISPATCH_DESTINATION_COUNT &&
             chosen_slot < 0; ++old_destination) {
                for (int new_destination = 0;
                     new_destination <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++new_destination) {
                        if (new_destination ==
                            old_destination) {
                                continue;
                        }
                        reset_dispatch_test();
                        if (force_uncorroborated_arrival(
                                    81, 0, old_destination,
                                    8) < 0) {
                                continue;
                        }
                        ++held_candidates;
                        int slot = find_train_job(81);
                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        old_generation =
                                job->plan_generation;
                        old_destination_node =
                                job->target_node;
                        tc2_dispatch_request current;
                        clear_request(
                                &current,
                                TC2_DISPATCH_MSG_STAGE);
                        current.train = job->train;
                        current.start_index =
                                TC2_DISPATCH_START_CURRENT;
                        current.speed = 120;
                        current.destination_index =
                                new_destination;
                        if (stage_job(&current) < 0) {
                                continue;
                        }
                        ++current_stage_successes;
                        if (
                            !dispatch_runtime[slot]
                                     .carry_ambiguity_active ||
                            dispatch_runtime[slot]
                                    .planned_launch_speed != 8) {
                                continue;
                        }
                        ++staged_candidates;
                        track_route carried =
                                dispatch_runtime[slot]
                                        .carry_ambiguity_footprint;
                        int outside = -1;
                        for (int node = 0;
                             node < TRACK_MAX; ++node) {
                                if (dispatch_track[node].type !=
                                            NODE_NONE &&
                                    !route_contains_node(
                                            &carried, node)) {
                                        outside = node;
                                        break;
                                }
                        }
                        track_route leave_and_reenter;
                        leave_and_reenter.node_count = 3;
                        leave_and_reenter.nodes[0] =
                                carried.nodes[0];
                        leave_and_reenter.nodes[1] = outside;
                        leave_and_reenter.nodes[2] =
                                carried.nodes[0];
                        leave_and_reenter.distance_mm = 0;
                        leave_and_reenter
                                .optimization_cost_mm = 0;
                        leave_and_reenter.reversal_count = 0;
                        if (carried.node_count < 1 ||
                            outside < 0 ||
                            route_does_not_reenter_before_localization(
                                    &leave_and_reenter,
                                    &carried)) {
                                fprintf(stderr,
                                        "estimated CURRENT admitted a "
                                        "leave/re-enter ambiguity route\n");
                                return -1;
                        }
                        job->state = TC2_JOB_WAITING;
                        job->queue_sequence =
                                ++dispatch_queue_sequence;
                        job->job_launch_epoch = 1;
                        dispatch_runtime[slot]
                                .queue_sequence =
                                job->queue_sequence;
                        dispatch_runtime[slot]
                                .wait_since_tick = mock_now;
                        dispatch_runtime[slot]
                                .launch_epoch = 1;
                        if (prepare_waiting_job(
                                    slot, mock_now) != 0) {
                                continue;
                        }
                        process_preparing_jobs(mock_now);
                        if (job->state == TC2_JOB_READY) {
                                ++prepared_candidates;
                        }
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        track_route new_only;
                        int saved_anchor =
                                runtime
                                        ->reservation_anchor_offset;
                        if (job->state != TC2_JOB_READY ||
                            runtime->route.reversal_count != 0 ||
                            Tc2RouteExpectedSensors(
                                    dispatch_track,
                                    &runtime->route,
                                    runtime->monitor
                                            .confirmed_offset,
                                    runtime
                                            ->monitor_terminal_offset,
                                    &first, &second) < 2 ||
                            second.route_offset >=
                                    job->target_route_offset ||
                            Tc2RouteExpectedSensors(
                                    dispatch_track,
                                    &runtime->route,
                                    second.route_offset,
                                    runtime
                                            ->monitor_terminal_offset,
                                    &third, &fourth) < 1 ||
                            third.route_offset >=
                                    job->target_route_offset ||
                            build_safety_footprint_for_route(
                                    &runtime->route, 0,
                                    job->target_route_offset,
                                    job->destination_route_offset,
                                    job->destination_offset_mm,
                                    job->speed, &new_only) < 0) {
                                continue;
                        }
                        runtime->reservation_anchor_offset =
                                second.route_offset;
                        int release_tail =
                                footprint_tail_offset(
                                        runtime, job);
                        runtime->reservation_anchor_offset =
                                saved_anchor;
                        if (release_tail <=
                            runtime->leg_start_offset) {
                                continue;
                        }
                        ++sensor_candidates;
                        for (int offset = 0;
                             offset < carried.node_count;
                             ++offset) {
                                int node =
                                        carried.nodes[offset];
                                if (!route_contains_node(
                                            &new_only, node)) {
                                        carry_only_node = node;
                                        break;
                                }
                        }
                        if (carry_only_node < 0 ||
                            mock_reservations
                                    .owner_by_node[
                                            carry_only_node] !=
                                    job->train ||
                            mock_reservations
                                    .destination_by_train[
                                            job->train] !=
                                    job->target_node ||
                            job->plan_generation ==
                                    old_generation) {
                                carry_only_node = -1;
                                continue;
                        }
                        ++carry_candidates;
                        chosen_slot = slot;
                        first_destination =
                                old_destination;
                        second_destination =
                                new_destination;
                        break;
                }
        }
        if (chosen_slot < 0) {
                fprintf(stderr,
                        "no safe estimated CURRENT relocalization "
                        "route was found (staged=%d prepared=%d "
                        "sensors=%d carry=%d held=%d current=%d)\n",
                        staged_candidates, prepared_candidates,
                        sensor_candidates, carry_candidates,
                        held_candidates, current_stage_successes);
                return -1;
        }

        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[chosen_slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[chosen_slot];
        mock_now = job->ready_at_tick;
        launch_ready_jobs(mock_now);
        process_launching_jobs(mock_now);
        if (job->state != TC2_JOB_RUNNING ||
            runtime->command_speed != 8 ||
            !runtime->carry_ambiguity_active) {
                return -1;
        }

        train_sensor_attributed_event_t event;
        event.train = job->train;
        event.generation = job->plan_generation;
        event.timestamp = 1;
        event.sequence =
                job->launch_attributed_sequence + 1;
        if (event.sequence == 0) ++event.sequence;
        event.sensor_index = runtime->start_node;
        event.arrival_tick = mock_now + 1;
        if (process_sensor_observation(
                    chosen_slot, &event,
                    event.arrival_tick,
                    event.arrival_tick) != 0 ||
            !runtime->carry_ambiguity_active ||
            job->duplicate_sensor_count != 1 ||
            mock_reservations.owner_by_node[
                    carry_only_node] != job->train) {
                fprintf(stderr,
                        "pre-origin catch-up event changed legacy "
                        "ownership\n");
                return -1;
        }

        int distance;
        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, &runtime->route,
                    runtime->monitor.confirmed_offset,
                    first.route_offset, &distance) < 0) {
                return -1;
        }
        ++event.sequence;
        if (event.sequence == 0) ++event.sequence;
        event.sensor_index = first.node_index;
        event.arrival_tick =
                runtime->last_confirmed_tick +
                Tc2MotionFastTravelTicks(
                        runtime->command_speed,
                        distance) + 5;
        if (process_sensor_observation(
                    chosen_slot, &event,
                    event.arrival_tick,
                    event.arrival_tick) != 0 ||
            !runtime->carry_ambiguity_active ||
            runtime->reservation_anchor_offset !=
                    runtime->leg_start_offset ||
            mock_reservations.owner_by_node[
                    carry_only_node] != job->train ||
            !job->position_estimated) {
                fprintf(stderr,
                        "first expected evidence released legacy "
                        "ownership\n");
                return -1;
        }

        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, &runtime->route,
                    first.route_offset,
                    second.route_offset, &distance) < 0) {
                return -1;
        }
        ++event.sequence;
        if (event.sequence == 0) ++event.sequence;
        event.sensor_index = second.node_index;
        event.arrival_tick =
                runtime->last_confirmed_tick +
                Tc2MotionFastTravelTicks(
                        runtime->command_speed,
                        distance) + 5;
        if (process_sensor_observation(
                    chosen_slot, &event,
                    event.arrival_tick,
                    event.arrival_tick) != 0 ||
            !runtime->carry_ambiguity_active ||
            !job->position_estimated ||
            runtime->reservation_anchor_offset !=
                    first.route_offset ||
            mock_reservations.owner_by_node[
                    carry_only_node] != job->train) {
                fprintf(stderr,
                        "second ordered evidence released legacy "
                        "ownership before the delayed tail margin\n");
                return -1;
        }

        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, &runtime->route,
                    second.route_offset,
                    third.route_offset, &distance) < 0) {
                return -1;
        }
        ++event.sequence;
        if (event.sequence == 0) ++event.sequence;
        event.sensor_index = third.node_index;
        event.arrival_tick =
                runtime->last_confirmed_tick +
                Tc2MotionFastTravelTicks(
                        runtime->command_speed,
                        distance) + 5;
        if (process_sensor_observation(
                    chosen_slot, &event,
                    event.arrival_tick,
                    event.arrival_tick) != 0 ||
            runtime->carry_ambiguity_active ||
            job->position_estimated ||
            runtime->reservation_anchor_offset !=
                    second.route_offset ||
            mock_reservations.owner_by_node[
                    carry_only_node] == job->train ||
            runtime->command_speed < 1 ||
            runtime->command_speed > job->speed) {
                fprintf(stderr,
                        "tail-delayed ordered evidence did not localize and "
                        "release legacy ownership old=%d new=%d "
                        "carry=%d estimated=%d anchor=%d/%d owner=%d "
                        "speed=%d/%d\n",
                        first_destination, second_destination,
                        runtime->carry_ambiguity_active,
                        job->position_estimated,
                        runtime->reservation_anchor_offset,
                        second.route_offset,
                        mock_reservations.owner_by_node[
                                carry_only_node],
                        runtime->command_speed, job->speed);
                return -1;
        }

        /*
         * A train-attributed event arriving after CURRENT staging but before
         * plan replacement must not disappear into the preparation
         * baseline. The expected-plan CAS is never attempted, so the old
         * hold remains byte-for-byte owned under its old identity.
         */
        reset_dispatch_test();
        if (force_uncorroborated_arrival(
                    82, 0, 3, 30) < 0) {
                return -1;
        }
        int slot = find_train_job(82);
        job = &dispatch_jobs[slot];
        old_generation = job->plan_generation;
        old_destination_node = job->target_node;
        int old_owners[TRACK_MAX];
        for (int node = 0; node < TRACK_MAX; ++node) {
                old_owners[node] =
                        mock_reservations.owner_by_node[node];
        }
        tc2_dispatch_request current;
        clear_request(&current, TC2_DISPATCH_MSG_STAGE);
        current.train = job->train;
        current.start_index =
                TC2_DISPATCH_START_CURRENT;
        current.speed = 25;
        current.destination_index = 5;
        if (stage_job(&current) < 0) return -1;
        train_sensor_attributed_event_t staged_event;
        staged_event.sensor_index =
                dispatch_runtime[slot].start_node;
        staged_event.train = job->train;
        staged_event.generation = old_generation;
        staged_event.sequence =
                dispatch_runtime[slot]
                        .stage_attributed_sequence + 1;
        if (staged_event.sequence == 0) {
                ++staged_event.sequence;
        }
        staged_event.timestamp = 2;
        staged_event.arrival_tick = mock_now;
        mock_record_sensor_event(&staged_event);
        job->state = TC2_JOB_WAITING;
        if (prepare_waiting_job(slot, mock_now) != -1 ||
            job->state != TC2_JOB_FAILED ||
            job->failure_reason !=
                    TC2_FAILURE_SENSOR_SEQUENCE ||
            mock_reservations.generation_by_train[
                    job->train] != old_generation ||
            mock_reservations.destination_by_train[
                    job->train] != old_destination_node) {
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (mock_reservations.owner_by_node[node] !=
                    old_owners[node]) {
                        fprintf(stderr,
                                "stage/preparation event changed old "
                                "reservation at node %d\n",
                                node);
                        return -1;
                }
        }

        reset_dispatch_test();
        if (force_uncorroborated_arrival(
                    84, 0, 4, 30) < 0) {
                return -1;
        }
        slot = find_train_job(84);
        job = &dispatch_jobs[slot];
        old_generation = job->plan_generation;
        old_destination_node = job->target_node;
        for (int node = 0; node < TRACK_MAX; ++node) {
                old_owners[node] =
                        mock_reservations.owner_by_node[node];
        }
        ++mock_can_health.turnout_changes;
        clear_request(&current, TC2_DISPATCH_MSG_STAGE);
        current.train = job->train;
        current.start_index =
                TC2_DISPATCH_START_CURRENT;
        current.speed = 25;
        current.destination_index = 1;
        if (stage_job(&current) == 0 ||
            job->state != TC2_JOB_ARRIVED ||
            mock_reservations.generation_by_train[
                    job->train] != old_generation ||
            mock_reservations.destination_by_train[
                    job->train] != old_destination_node) {
                fprintf(stderr,
                        "turnout change during ARRIVED hold was "
                        "absorbed by CURRENT staging\n");
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (mock_reservations.owner_by_node[node] !=
                    old_owners[node]) {
                        return -1;
                }
        }

        /*
         * The equally important race is after stage_job has copied the
         * confirmed plan but before prepare_waiting_job attempts its CAS.
         * That change must be compared with the preserved ARRIVED baseline,
         * not absorbed as a fresh preparation baseline.
         */
        reset_dispatch_test();
        if (force_uncorroborated_arrival(
                    85, 0, 2, 30) < 0) {
                return -1;
        }
        slot = find_train_job(85);
        job = &dispatch_jobs[slot];
        old_generation = job->plan_generation;
        old_destination_node = job->target_node;
        for (int node = 0; node < TRACK_MAX; ++node) {
                old_owners[node] =
                        mock_reservations.owner_by_node[node];
        }
        clear_request(&current, TC2_DISPATCH_MSG_STAGE);
        current.train = job->train;
        current.start_index =
                TC2_DISPATCH_START_CURRENT;
        current.speed = 25;
        current.destination_index = 6;
        if (stage_job(&current) < 0) return -1;
        ++mock_can_health.turnout_changes;
        job->state = TC2_JOB_WAITING;
        if (prepare_waiting_job(slot, mock_now) != -1 ||
            job->state != TC2_JOB_FAILED ||
            job->failure_reason != TC2_FAILURE_CAN_HEALTH ||
            mock_reservations.generation_by_train[
                    job->train] != old_generation ||
            mock_reservations.destination_by_train[
                    job->train] != old_destination_node) {
                fprintf(stderr,
                        "stage-to-prepare turnout race was not "
                        "rejected before plan CAS\n");
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (mock_reservations.owner_by_node[node] !=
                    old_owners[node]) {
                        return -1;
                }
        }
        return 0;
}

static int check_all_estimated_destination_pairs_plan(void) {
        int localization_chains_checked = 0;
        int safely_held_pairs = 0;
        for (int old_destination = 0;
             old_destination <
                     TC2_DISPATCH_DESTINATION_COUNT;
             ++old_destination) {
                for (int new_destination = 0;
                     new_destination <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++new_destination) {
                        reset_dispatch_test();
                        if (force_uncorroborated_arrival(
                                    83, 0, old_destination,
                                    8) < 0) {
                                return -1;
                        }
                        int slot = find_train_job(83);
                        tc2_dispatch_request current;
                        clear_request(
                                &current,
                                TC2_DISPATCH_MSG_STAGE);
                        current.train = 83;
                        current.start_index =
                                TC2_DISPATCH_START_CURRENT;
                        current.speed = 8;
                        current.destination_index =
                                new_destination;
                        if (stage_job(&current) < 0) {
                                return -1;
                        }
                        dispatch_jobs[slot].state =
                                TC2_JOB_WAITING;
                        dispatch_jobs[slot].queue_sequence =
                                ++dispatch_queue_sequence;
                        dispatch_runtime[slot]
                                .wait_since_tick = mock_now;
                        dispatch_runtime[slot]
                                .launch_epoch = 1;
                        dispatch_jobs[slot]
                                .job_launch_epoch = 1;
                        if (prepare_waiting_job(
                                    slot, mock_now) != 0) {
                                /*
                                 * An uncorroborated destination centre can
                                 * straddle an unobserved turnout.  If neither
                                 * direction can reach two localization
                                 * sensors without changing that turnout
                                 * under the body, WAITING is the only safe
                                 * result.  Explicit operator `reroute` uses
                                 * reverse-first recovery and is covered by
                                 * the capture-39/40 end-to-end cases.
                                 */
                                if (dispatch_jobs[slot].state !=
                                            TC2_JOB_WAITING ||
                                    !dispatch_runtime[slot]
                                             .carry_ambiguity_active ||
                                    dispatch_jobs[slot]
                                             .plan_generation != 1 ||
                                    mock_reservations
                                             .generation_by_train[83] != 1) {
                                        fprintf(stderr,
                                                "estimated CURRENT pair "
                                                "D%d->D%d failed unsafely\n",
                                                old_destination + 1,
                                                new_destination + 1);
                                        return -1;
                                }
                                ++safely_held_pairs;
                                continue;
                        }
                        if (dispatch_jobs[slot].state !=
                                    TC2_JOB_PREPARING &&
                            dispatch_jobs[slot].state !=
                                    TC2_JOB_ARRIVED) {
                                return -1;
                        }
                        if (dispatch_runtime[slot]
                                    .localization_only) {
                                int reached_requested_route = 0;
                                for (int hop = 0;
                                     hop < 16; ++hop) {
                                        process_preparing_jobs(
                                                mock_now);
                                        tc2_dispatch_job_snapshot *job =
                                                &dispatch_jobs[slot];
                                        tc2_dispatch_runtime *runtime =
                                                &dispatch_runtime[slot];
                                        if (job->state !=
                                            TC2_JOB_READY) {
                                                return -1;
                                        }
                                        int prior_sensor =
                                                runtime
                                                        ->leg_start_offset;
                                        for (int offset =
                                                     runtime
                                                             ->leg_start_offset;
                                             offset <
                                                     job
                                                             ->target_route_offset;
                                             ++offset) {
                                                if (dispatch_track[
                                                            runtime
                                                                    ->route
                                                                    .nodes[
                                                                            offset]]
                                                            .type ==
                                                    NODE_SENSOR) {
                                                        prior_sensor =
                                                                offset;
                                                }
                                        }
                                        job->state =
                                                TC2_JOB_BRAKING;
                                        job->current_route_offset =
                                                job->target_route_offset;
                                        job->current_node =
                                                job->target_node;
                                        runtime
                                                ->reservation_anchor_offset =
                                                prior_sensor;
                                        runtime->target_seen = 1;
                                        runtime
                                                ->target_corroborated = 0;
                                        runtime->stop_purpose =
                                                TC2_STOP_DESTINATION;
                                        runtime->settle_at_tick =
                                                mock_now;
                                        if (update_remaining_footprint(
                                                    slot) < 0) {
                                                return -1;
                                        }
                                        process_braking_and_reversing(
                                                mock_now);
                                        if (dispatch_jobs[slot].state !=
                                                    TC2_JOB_WAITING ||
                                            dispatch_jobs[slot]
                                                    .destination_index !=
                                                    new_destination) {
                                                fprintf(stderr,
                                                        "localization phase "
                                                        "did not restage "
                                                        "requested D%d\n",
                                                        new_destination + 1);
                                                return -1;
                                        }
                                        if (prepare_waiting_job(
                                                    slot,
                                                    mock_now) != 0) {
                                                return -1;
                                        }
                                        if (!dispatch_runtime[slot]
                                                     .localization_only) {
                                                int target =
                                                        dispatch_jobs[slot]
                                                                .target_node;
                                                int side_a =
                                                        TrackFindNodeByName(
                                                                dispatch_track,
                                                                Tc2DispatchDestinationSensorA(
                                                                        new_destination));
                                                int side_b =
                                                        TrackFindNodeByName(
                                                                dispatch_track,
                                                                Tc2DispatchDestinationSensorB(
                                                                        new_destination));
                                                if (target != side_a &&
                                                    target != side_b) {
                                                        return -1;
                                                }
                                                reached_requested_route = 1;
                                                break;
                                        }
                                }
                                if (!reached_requested_route) {
                                        fprintf(stderr,
                                                "localization chain did "
                                                "not converge to D%d\n",
                                                new_destination + 1);
                                        return -1;
                                }
                                ++localization_chains_checked;
                        }
                }
        }
        /* Dedicated capture regressions exercise executable localization
         * and reverse-first recovery.  This exhaustive matrix additionally
         * requires at least one physically ambiguous pair to remain safely
         * held instead of changing an unobserved turnout under the train. */
        (void)localization_chains_checked;
        return safely_held_pairs > 0 ? 0 : -1;
}

static int check_estimated_current_conflict_waits(void) {
        for (int mode = 0; mode < 2; ++mode) {
                reset_dispatch_test();
                if (force_uncorroborated_arrival(
                            86, 0, 0, 8) < 0) {
                        return -1;
                }
                int slot = find_train_job(86);
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                int destination = -1;
                int target_a = -1;
                int target_b = -1;
                for (int candidate = 1;
                     candidate <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++candidate) {
                        int a = TrackFindNodeByName(
                                dispatch_track,
                                Tc2DispatchDestinationSensorA(
                                        candidate));
                        int b = TrackFindNodeByName(
                                dispatch_track,
                                Tc2DispatchDestinationSensorB(
                                        candidate));
                        if (a >= 0 && b >= 0 &&
                            mock_reservations.owner_by_node[a] == 0 &&
                            mock_reservations.owner_by_node[b] == 0) {
                                destination = candidate;
                                target_a = a;
                                target_b = b;
                                break;
                        }
                }
                if (destination < 0) return -1;
                unsigned int old_generation =
                        job->plan_generation;
                int old_destination = job->target_node;
                tc2_dispatch_request current;
                clear_request(
                        &current, TC2_DISPATCH_MSG_STAGE);
                current.train = job->train;
                current.start_index =
                        TC2_DISPATCH_START_CURRENT;
                current.speed = 25;
                current.destination_index = destination;
                if (stage_job(&current) < 0) return -1;
                if (mode == 0) {
                        int physical[4] = {
                                target_a, target_b,
                                physical_reverse_index(target_a),
                                physical_reverse_index(target_b)};
                        for (int index = 0; index < 4; ++index) {
                                if (physical[index] >= 0) {
                                        mock_reservations
                                                .owner_by_node[
                                                        physical[index]] =
                                                222;
                                }
                        }
                } else {
                        if (block_node(target_a, 1) < 0 ||
                            block_node(target_b, 1) < 0) {
                                return -1;
                        }
                }
                int expected_owners[TRACK_MAX];
                for (int node = 0; node < TRACK_MAX; ++node) {
                        expected_owners[node] =
                                mock_reservations
                                        .owner_by_node[node];
                }
                job->state = TC2_JOB_WAITING;
                job->queue_sequence =
                        ++dispatch_queue_sequence;
                dispatch_runtime[slot].queue_sequence =
                        job->queue_sequence;
                dispatch_runtime[slot].wait_since_tick =
                        mock_now;
                dispatch_runtime[slot].launch_epoch = 1;
                job->job_launch_epoch = 1;
                int prepared =
                        prepare_waiting_job(
                                slot, mock_now);
                if (mode == 0) {
                        /*
                         * A managed owner only at the distant destination
                         * must not pin an estimated CURRENT train at its
                         * origin.  It may take a short localization or
                         * rolling-authority hop, but that local footprint
                         * must leave the foreign target untouched.
                         */
                        int target_physical[4] = {
                                target_a, target_b,
                                physical_reverse_index(target_a),
                                physical_reverse_index(target_b)};
                        int stole_target = 0;
                        for (int index = 0; index < 4; ++index) {
                                int node =
                                        target_physical[index];
                                if (node >= 0 &&
                                    mock_reservations
                                            .owner_by_node[node] !=
                                            222) {
                                        stole_target = 1;
                                }
                        }
                        if (prepared != 0 ||
                            job->state != TC2_JOB_PREPARING ||
                            !dispatch_runtime[slot].route_valid ||
                            stole_target ||
                            mock_speed_batch_calls != 0 ||
                            mock_positive_speed_calls != 0 ||
                            job->plan_generation ==
                                    old_generation) {
                                fprintf(stderr,
                                        "estimated CURRENT did not take "
                                        "a bounded local hop before a "
                                        "distant managed destination\n");
                                return -1;
                        }
                        continue;
                }
                if (prepared != 1 ||
                    job->state != TC2_JOB_WAITING ||
                    dispatch_runtime[slot].route_valid ||
                    dispatch_runtime[slot].localization_only ||
                    !dispatch_runtime[slot]
                             .carry_ambiguity_active ||
                    !job->position_estimated ||
                    mock_speed_batch_calls != 0 ||
                    mock_positive_speed_calls != 0 ||
                    mock_reservations.generation_by_train[
                            job->train] != old_generation ||
                    mock_reservations.destination_by_train[
                            job->train] != old_destination) {
                        fprintf(stderr,
                                "estimated CURRENT moved to localize "
                                "through a blocked destination\n");
                        return -1;
                }
                for (int node = 0; node < TRACK_MAX; ++node) {
                        if (mock_reservations.owner_by_node[node] !=
                            expected_owners[node]) {
                                return -1;
                        }
                }
                if (block_node(target_a, 0) < 0 ||
                    block_node(target_b, 0) < 0) {
                        return -1;
                }
                if (prepare_waiting_job(
                            slot, mock_now) != 0) {
                        fprintf(stderr,
                                "estimated CURRENT did not leave WAIT "
                                "after the conflict cleared\n");
                        return -1;
                }
        }
        return 0;
}

static int check_exact_current_ignores_distant_managed_reservation(void) {
        int directed_sensor = -1;
        int destination = -1;
        int distant_offset = -1;
        int distant_node = -1;
        track_route baseline_route = {0};
        int baseline_authority_end = -1;

        /*
         * First find a real, exactly localized CURRENT trip whose bounded
         * initial authority leaves at least one unowned physical node in the
         * future suffix.  That suffix must not be treated as occupied local
         * authority merely because a managed train holds it.
         */
        for (int sensor = 0;
             sensor < TRAIN_SENSOR_COUNT &&
             directed_sensor < 0; ++sensor) {
                for (int candidate = 0;
                     candidate <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++candidate) {
                        reset_dispatch_test();
                        if (force_exact_directed_hold(
                                    81, sensor, 20) < 0) {
                                continue;
                        }
                        tc2_dispatch_request current;
                        clear_request(
                                &current, TC2_DISPATCH_MSG_STAGE);
                        current.train = 81;
                        current.start_index =
                                TC2_DISPATCH_START_CURRENT;
                        current.speed = 20;
                        current.destination_index =
                                candidate;
                        if (stage_job(&current) < 0) continue;
                        int slot = find_train_job(81);
                        if (slot < 0) continue;
                        dispatch_jobs[slot].state =
                                TC2_JOB_WAITING;
                        dispatch_jobs[slot].queue_sequence =
                                ++dispatch_queue_sequence;
                        dispatch_runtime[slot]
                                .wait_since_tick = mock_now;
                        dispatch_runtime[slot]
                                .launch_epoch = 1;
                        dispatch_jobs[slot]
                                .job_launch_epoch = 1;
                        if (prepare_waiting_job(
                                    slot, mock_now) != 0) {
                                continue;
                        }
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        if (!runtime->route_valid ||
                            !runtime
                                     ->rolling_authority_active ||
                            runtime->authority_end_offset < 0 ||
                            runtime->authority_end_offset >=
                                    dispatch_jobs[slot]
                                            .target_route_offset) {
                                continue;
                        }
                        for (int offset =
                                     runtime
                                             ->authority_end_offset +
                                     1;
                             offset <=
                                     dispatch_jobs[slot]
                                             .target_route_offset;
                             ++offset) {
                                int node =
                                        runtime->route
                                                .nodes[offset];
                                int reverse =
                                        physical_reverse_index(
                                                node);
                                if (mock_reservations
                                            .owner_by_node[node] !=
                                            0 ||
                                    (reverse >= 0 &&
                                     mock_reservations
                                             .owner_by_node[
                                                     reverse] !=
                                             0) ||
                                    route_contains_node(
                                            &runtime
                                                     ->safety_footprint,
                                            node) ||
                                    (reverse >= 0 &&
                                     route_contains_node(
                                             &runtime
                                                      ->safety_footprint,
                                             reverse))) {
                                        continue;
                                }
                                directed_sensor = sensor;
                                destination = candidate;
                                distant_offset = offset;
                                distant_node = node;
                                baseline_route =
                                        runtime->route;
                                baseline_authority_end =
                                        runtime
                                                ->authority_end_offset;
                                break;
                        }
                        if (directed_sensor >= 0) break;
                }
        }
        if (directed_sensor < 0 || destination < 0 ||
            distant_offset <= baseline_authority_end ||
            distant_node < 0) {
                fprintf(stderr,
                        "no exact CURRENT route exposed a distant "
                        "unowned suffix fixture\n");
                return -1;
        }

        reset_dispatch_test();
        if (force_exact_directed_hold(
                    81, directed_sensor, 20) < 0) {
                return -1;
        }
        track_route distant_hold = {0};
        distant_hold.node_count = 1;
        distant_hold.nodes[0] = distant_node;
        track_reservation_conflict conflict;
        unsigned int peer_generation = 0;
        if (TrackReservationTryWindowToGeneration(
                    &mock_reservations, dispatch_track,
                    &distant_hold, 82, distant_node,
                    &conflict, &peer_generation) != 0 ||
            peer_generation == 0) {
                fprintf(stderr,
                        "could not install distant managed reservation "
                        "node=%d owner=%d conflict=%d\n",
                        distant_node,
                        mock_reservations
                                .owner_by_node[distant_node],
                        conflict.owner_train);
                return -1;
        }
        int peer_slot = find_empty_job();
        if (peer_slot < 0) return -1;
        dispatch_jobs[peer_slot].train = 82;
        dispatch_jobs[peer_slot].start_index =
                TC2_DISPATCH_START_CURRENT;
        dispatch_jobs[peer_slot].speed = 20;
        dispatch_jobs[peer_slot].state =
                TC2_JOB_ARRIVED;
        dispatch_jobs[peer_slot].target_node =
                distant_node;
        dispatch_jobs[peer_slot].current_node =
                distant_node;
        dispatch_jobs[peer_slot].plan_generation =
                peer_generation;
        dispatch_jobs[peer_slot].hold_active = 1;

        tc2_dispatch_request current;
        clear_request(&current, TC2_DISPATCH_MSG_STAGE);
        current.train = 81;
        current.start_index =
                TC2_DISPATCH_START_CURRENT;
        current.speed = 20;
        current.destination_index = destination;
        if (stage_job(&current) < 0) return -1;
        int slot = find_train_job(81);
        if (slot < 0) return -1;
        dispatch_jobs[slot].state = TC2_JOB_WAITING;
        dispatch_jobs[slot].queue_sequence =
                ++dispatch_queue_sequence;
        dispatch_runtime[slot].wait_since_tick =
                mock_now;
        dispatch_runtime[slot].launch_epoch = 1;
        dispatch_jobs[slot].job_launch_epoch = 1;
        if (prepare_waiting_job(slot, mock_now) != 0) {
                fprintf(stderr,
                        "distant managed reservation blocked exact "
                        "CURRENT local authority\n");
                return -1;
        }
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            !runtime->rolling_authority_active ||
            runtime->authority_end_offset >
                    baseline_authority_end ||
            runtime->authority_end_offset >=
                    distant_offset ||
            runtime->route.node_count !=
                    baseline_route.node_count ||
            mock_reservations.owner_by_node[distant_node] !=
                    82) {
                fprintf(stderr,
                        "distant managed hold changed CURRENT local "
                        "plan end=%d baseline=%d distant=%d route=%d/%d "
                        "owner=%d state=%d\n",
                        runtime->authority_end_offset,
                        baseline_authority_end,
                        distant_offset,
                        runtime->route.node_count,
                        baseline_route.node_count,
                        mock_reservations
                                .owner_by_node[distant_node],
                        dispatch_jobs[slot].state);
                return -1;
        }
        for (int offset = 0;
             offset < baseline_route.node_count; ++offset) {
                if (runtime->route.nodes[offset] !=
                            baseline_route.nodes[offset]) {
                        fprintf(stderr,
                                "distant managed hold rerouted exact "
                                "CURRENT at offset=%d\n",
                                offset);
                        return -1;
                }
        }
        return 0;
}

static int check_fixed_starts_ignore_distant_managed_reservation(void) {
        int selected_start = -1;
        int selected_destination = -1;
        int distant_offset = -1;
        int distant_node = -1;
        int baseline_authority_end = -1;
        track_route baseline_route = {0};

        /*
         * Use a real A-F route and locate one physical node in the immutable
         * route suffix beyond its first bounded authority.  A managed owner on
         * that distant node must not alter or block the local launch window.
         */
        for (int start = 0;
             start < TC2_DISPATCH_START_COUNT &&
             selected_start < 0; ++start) {
                for (int destination = 0;
                     destination <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++destination) {
                        reset_dispatch_test();
                        if (prepare_one_trip(
                                    81, start, destination,
                                    20) != 0) {
                                continue;
                        }
                        int slot = find_train_job(81);
                        if (slot < 0) continue;
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        if (!runtime->route_valid ||
                            !runtime->rolling_authority_active ||
                            runtime->authority_end_offset < 0 ||
                            runtime->authority_end_offset >=
                                    job->target_route_offset) {
                                continue;
                        }
                        for (int offset =
                                     runtime
                                             ->authority_end_offset +
                                     1;
                             offset <=
                                     job->target_route_offset;
                             ++offset) {
                                int node =
                                        runtime->route
                                                .nodes[offset];
                                int reverse =
                                        physical_reverse_index(
                                                node);
                                if (mock_reservations
                                            .owner_by_node[node] !=
                                            0 ||
                                    (reverse >= 0 &&
                                     mock_reservations
                                             .owner_by_node[
                                                     reverse] !=
                                             0) ||
                                    route_contains_node(
                                            &runtime
                                                     ->safety_footprint,
                                            node) ||
                                    (reverse >= 0 &&
                                     route_contains_node(
                                             &runtime
                                                      ->safety_footprint,
                                             reverse))) {
                                        continue;
                                }
                                selected_start = start;
                                selected_destination =
                                        destination;
                                distant_offset = offset;
                                distant_node = node;
                                baseline_authority_end =
                                        runtime
                                                ->authority_end_offset;
                                baseline_route =
                                        runtime->route;
                                break;
                        }
                        if (selected_start >= 0) break;
                }
        }
        if (selected_start < 0 ||
            selected_destination < 0 ||
            distant_offset <= baseline_authority_end ||
            distant_node < 0) {
                fprintf(stderr,
                        "no fixed A-F route exposed a distant unowned "
                        "suffix fixture\n");
                return -1;
        }

        reset_dispatch_test();
        track_route distant_hold = {0};
        distant_hold.node_count = 1;
        distant_hold.nodes[0] = distant_node;
        track_reservation_conflict conflict;
        unsigned int peer_generation = 0;
        if (TrackReservationTryWindowToGeneration(
                    &mock_reservations, dispatch_track,
                    &distant_hold, 82, distant_node,
                    &conflict, &peer_generation) != 0 ||
            peer_generation == 0) {
                fprintf(stderr,
                        "could not install fixed-route distant managed "
                        "reservation node=%d\n",
                        distant_node);
                return -1;
        }
        int peer_slot = find_empty_job();
        if (peer_slot < 0) return -1;
        dispatch_jobs[peer_slot].train = 82;
        dispatch_jobs[peer_slot].start_index =
                TC2_DISPATCH_START_CURRENT;
        dispatch_jobs[peer_slot].speed = 20;
        dispatch_jobs[peer_slot].state =
                TC2_JOB_ARRIVED;
        dispatch_jobs[peer_slot].target_node =
                distant_node;
        dispatch_jobs[peer_slot].current_node =
                distant_node;
        dispatch_jobs[peer_slot].plan_generation =
                peer_generation;
        dispatch_jobs[peer_slot].hold_active = 1;

        if (prepare_one_trip(
                    81, selected_start,
                    selected_destination, 20) != 0) {
                fprintf(stderr,
                        "distant managed reservation blocked fixed A-F "
                        "local authority\n");
                return -1;
        }
        int slot = find_train_job(81);
        if (slot < 0) return -1;
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (!runtime->route_valid ||
            !runtime->rolling_authority_active ||
            runtime->authority_end_offset >
                    baseline_authority_end ||
            runtime->authority_end_offset >=
                    distant_offset ||
            runtime->route.node_count !=
                    baseline_route.node_count ||
            mock_reservations.owner_by_node[
                    distant_node] != 82) {
                fprintf(stderr,
                        "distant managed owner changed fixed route/window "
                        "start=%d destination=%d end=%d/%d distant=%d "
                        "owner=%d\n",
                        selected_start, selected_destination,
                        runtime->authority_end_offset,
                        baseline_authority_end,
                        distant_offset,
                        mock_reservations
                                .owner_by_node[distant_node]);
                return -1;
        }
        for (int offset = 0;
             offset < baseline_route.node_count; ++offset) {
                if (runtime->route.nodes[offset] !=
                            baseline_route.nodes[offset]) {
                        fprintf(stderr,
                                "distant managed owner rerouted fixed A-F "
                                "trip at offset=%d\n",
                                offset);
                        return -1;
                }
        }
        return 0;
}

/*
 * A pending launch batch is not proof of movement.  Cancelling that job must
 * detach the old confirmation token immediately so a late batch reply cannot
 * resurrect LAUNCHING after the priority zero command.  The physical route
 * remains reserved through coast/settle and is released exactly once by the
 * subsequent operator remove.
 */
static int check_cancel_pending_launch_batch_then_remove_once(void) {
        reset_dispatch_test();
        if (prepare_one_trip(14, 0, 0, 20) != 0) return -1;
        int slot = find_train_job(14);
        if (slot < 0) return -1;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        unsigned int generation = job->plan_generation;
        unsigned char owned_before[TRACK_MAX];
        int owner_count = 0;
        for (int node = 0; node < TRACK_MAX; ++node) {
                owned_before[node] =
                        mock_reservations.owner_by_node[node] == 14;
                owner_count += owned_before[node] ? 1 : 0;
        }
        if (job->state != TC2_JOB_READY || generation == 0 ||
            owner_count < 1) {
                return -1;
        }

        mock_batch_auto_complete = 0;
        mock_now = job->ready_at_tick;
        launch_ready_jobs(mock_now);
        if (job->state != TC2_JOB_LAUNCHING ||
            runtime->launch_batch_token == 0 ||
            runtime->launch_batch_index != 0 ||
            runtime->launch_wave_tick != mock_now ||
            mock_batch_status.state != CAN_BATCH_PENDING) {
                fprintf(stderr,
                        "pending launch fixture did not enter LAUNCHING "
                        "state=%d token=%u index=%d wave=%d/%d batch=%d\n",
                        job->state, runtime->launch_batch_token,
                        runtime->launch_batch_index,
                        runtime->launch_wave_tick, mock_now,
                        mock_batch_status.state);
                return -1;
        }
        int positive_before_cancel =
                mock_positive_commands_by_train[14];
        if (cancel_job(14) < 0 ||
            job->state != TC2_JOB_CANCEL_BRAKING ||
            job->command_speed != 0 ||
            runtime->command_speed != 0 ||
            runtime->launch_batch_token != 0 ||
            runtime->launch_batch_index != -1 ||
            runtime->launch_wave_tick != -1 ||
            mock_batch_status.state != CAN_BATCH_FAILED) {
                fprintf(stderr,
                        "cancel did not detach pending launch batch "
                        "state=%d speed=%d/%d token=%u index=%d wave=%d "
                        "batch=%d\n",
                        job->state, job->command_speed,
                        runtime->command_speed,
                        runtime->launch_batch_token,
                        runtime->launch_batch_index,
                        runtime->launch_wave_tick,
                        mock_batch_status.state);
                return -1;
        }
        if (mock_reservations.generation_by_train[14] != generation ||
            mock_positive_commands_by_train[14] !=
                    positive_before_cancel) {
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (owned_before[node] &&
                    mock_reservations.owner_by_node[node] != 14) {
                        fprintf(stderr,
                                "pending-launch cancel released %s before "
                                "physical settle/remove\n",
                                dispatch_track[node].name);
                        return -1;
                }
        }

        int settle = runtime->settle_at_tick;
        if (settle < 0) return -1;
        process_launching_jobs(settle);
        process_braking_and_reversing(settle);
        if (job->state != TC2_JOB_STOPPED ||
            runtime->launch_batch_token != 0 ||
            mock_reservations.generation_by_train[14] != generation) {
                fprintf(stderr,
                        "pending-launch cancel did not settle to one "
                        "removable STOPPED state=%d token=%u generation=%u/%u\n",
                        job->state, runtime->launch_batch_token,
                        generation,
                        mock_reservations.generation_by_train[14]);
                return -1;
        }
        mock_now = settle;
        if (remove_job(14) < 0 || find_train_job(14) >= 0) {
                fprintf(stderr,
                        "first remove after pending-launch cancel failed\n");
                return -1;
        }
        for (int node = 0; node < TRACK_MAX; ++node) {
                if (owned_before[node] &&
                    mock_reservations.owner_by_node[node] != 0) {
                        fprintf(stderr,
                                "remove retained pending-launch node %s\n",
                                dispatch_track[node].name);
                        return -1;
                }
        }
        if (remove_job(14) == 0) {
                fprintf(stderr,
                        "second remove unexpectedly succeeded\n");
                return -1;
        }
        return 0;
}

static int check_prelaunch_cancel_and_global_fail_close(void) {
        reset_dispatch_test();
        if (prepare_one_trip(90, 0, 2, 30) != 0) return -1;
        int slot = find_train_job(90);
        train_sensor_attributed_event_t event;
        event.sensor_index =
                dispatch_runtime[slot].route.nodes[
                        dispatch_runtime[slot]
                                .monitor.confirmed_offset + 1];
        event.train = 90;
        event.generation = dispatch_jobs[slot].plan_generation;
        event.sequence = 1;
        event.timestamp = 1;
        event.arrival_tick = mock_now;
        mock_record_sensor_event(&event);
        mock_sensor_snapshot.attributed_count = 1;
        mock_now = dispatch_jobs[slot].ready_at_tick;
        launch_ready_jobs(mock_now);
        if (dispatch_jobs[slot].state != TC2_JOB_FAILED) {
                return -1;
        }

        reset_dispatch_test();
        if (prepare_one_trip(94, 0, 2, 30) != 0) return -1;
        slot = find_train_job(94);
        ++mock_sensor_snapshot.attribution_unavailable_count;
        mock_now = dispatch_jobs[slot].ready_at_tick;
        launch_ready_jobs(mock_now);
        if (dispatch_jobs[slot].state != TC2_JOB_FAILED) {
                fprintf(stderr,
                        "prelaunch attribution lookup failure was "
                        "accepted as a new baseline\n");
                return -1;
        }

        reset_dispatch_test();
        if (prepare_one_trip(91, 1, 3, 30) != 0) return -1;
        slot = find_train_job(91);
        if (cancel_job(91) < 0 ||
            dispatch_jobs[slot].state !=
                    TC2_JOB_CANCEL_BRAKING ||
            remove_job(91) == 0) {
                return -1;
        }
        mock_now = dispatch_runtime[slot].settle_at_tick;
        process_braking_and_reversing(mock_now);
        if (dispatch_jobs[slot].state != TC2_JOB_STOPPED ||
            remove_job(91) < 0) {
                return -1;
        }

        reset_dispatch_test();
        if (prepare_one_trip(92, 2, 4, 30) != 0) return -1;
        slot = find_train_job(92);
        mock_now = dispatch_jobs[slot].ready_at_tick;
        launch_ready_jobs(mock_now);
        process_launching_jobs(mock_now);
        if (dispatch_jobs[slot].state != TC2_JOB_RUNNING) {
                return -1;
        }
        ++mock_sensor_snapshot.attribution_unavailable_count;
        process_running_jobs(mock_now + 1);
        if (dispatch_jobs[slot].state != TC2_JOB_FAILED ||
            dispatch_jobs[slot].failure_reason !=
                    TC2_FAILURE_SENSOR_SEQUENCE) {
                return -1;
        }

        reset_dispatch_test();
        mock_can_health.rx_overflow = 1;
        clear_job(&dispatch_jobs[0]);
        clear_runtime(&dispatch_runtime[0]);
        dispatch_jobs[0].train = 93;
        if (can_health_is_safe(
                    0, 1, mock_now) == 0) return -1;
        return 0;
}

static int check_final_guard_and_braking_progress(void) {
        int checked_branch_guard = 0;
        int checked_braking_progress = 0;
        int checked_braking_coast_progress = 0;
        for (int destination = 0;
             destination < TC2_DISPATCH_DESTINATION_COUNT;
             ++destination) {
                reset_dispatch_test();
                if (prepare_one_trip(
                            100, destination %
                                    TC2_DISPATCH_START_COUNT,
                            destination, 50) != 0) {
                        continue;
                }
                int slot = find_train_job(100);
                tc2_dispatch_job_snapshot *job =
                        &dispatch_jobs[slot];
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[slot];
                /*
                 * The dispatcher now starts with a bounded rolling window.
                 * This test exercises the final destination guard and coast
                 * behavior, so advance the fixture to the atomically granted
                 * final authority before inspecting that guard.
                 */
                track_route final_footprint;
                track_reservation_conflict final_conflict;
                unsigned int final_generation = 0;
                if (build_safety_footprint_for_route(
                            &runtime->route, 0,
                            job->target_route_offset,
                            job->destination_route_offset,
                            job->destination_offset_mm,
                            job->speed,
                            &final_footprint) < 0 ||
                    TrackReservationServerUpdateWindow(
                            dispatch_reservation_tid,
                            &final_footprint, job->train,
                            job->target_node,
                            job->plan_generation,
                            &final_conflict,
                            &final_generation) != 0 ||
                    final_generation !=
                            job->plan_generation) {
                        return -1;
                }
                runtime->safety_footprint =
                        final_footprint;
                runtime->authority_end_offset =
                        runtime->route.node_count - 1;
                runtime->authority_center_ceiling_mm =
                        job->destination_distance_mm;
                runtime->authority_prefetch_active = 0;
                track_route reachable;
                reachable.node_count = 0;
                reachable.distance_mm = 0;
                reachable.optimization_cost_mm = 0;
                reachable.reversal_count = 0;
                if (append_forward_guard_reachable(
                            &reachable, job->target_node,
                            Tc2MotionBrakingDistanceMm(
                                    job->speed)) < 0) {
                        return -1;
                }
                for (int offset = 0;
                     offset < reachable.node_count; ++offset) {
                        int node = reachable.nodes[offset];
                        if (!route_contains_node(
                                    &runtime->safety_footprint,
                                    node)) {
                                return -1;
                        }
                        if (dispatch_track[node].type ==
                                    NODE_BRANCH &&
                            dispatch_track[node]
                                    .edge[DIR_STRAIGHT].dest &&
                            dispatch_track[node]
                                    .edge[DIR_CURVED].dest) {
                                int straight = (int)(
                                        dispatch_track[node]
                                                .edge[DIR_STRAIGHT]
                                                .dest -
                                        dispatch_track);
                                int curved = (int)(
                                        dispatch_track[node]
                                                .edge[DIR_CURVED]
                                                .dest -
                                        dispatch_track);
                                if (route_contains_node(
                                            &runtime
                                                     ->safety_footprint,
                                            straight) &&
                                    route_contains_node(
                                            &runtime
                                                     ->safety_footprint,
                                            curved)) {
                                        checked_branch_guard = 1;
                                }
                        }
                }

                if (!checked_braking_coast_progress) {
                        tc2_route_sensor_point next;
                        tc2_route_sensor_point next_next;
                        if (Tc2RouteExpectedSensors(
                                    dispatch_track,
                                    &runtime->route,
                                    runtime->monitor
                                            .confirmed_offset,
                                    runtime
                                            ->monitor_terminal_offset,
                                    &next, &next_next) >= 1 &&
                            next.route_offset <
                                    runtime->leg_end_offset) {
                                int distance;
                                if (TrackRouteDistanceBetweenOffsets(
                                            dispatch_track,
                                            &runtime->route,
                                            runtime->monitor
                                                    .confirmed_offset,
                                            next.route_offset,
                                            &distance) < 0) {
                                        return -1;
                                }
                                runtime->last_confirmed_tick =
                                        mock_now;
                                runtime->command_speed = 0;
                                runtime->stop_purpose =
                                        TC2_STOP_DESTINATION;
                                job->state = TC2_JOB_BRAKING;
                                train_sensor_attributed_event_t event;
                                event.sensor_index =
                                        next.node_index;
                                event.train = job->train;
                                event.generation =
                                        job->plan_generation;
                                event.sequence = 1;
                                event.timestamp = 1;
                                event.arrival_tick =
                                        mock_now +
                                        Tc2MotionFastTravelTicks(
                                                job->speed,
                                                distance) +
                                        5;
                                if (process_sensor_observation(
                                            slot, &event,
                                            event.arrival_tick,
                                            event.arrival_tick) < 0 ||
                                    job->state != TC2_JOB_BRAKING ||
                                    job->current_route_offset !=
                                            next.route_offset) {
                                        fprintf(stderr,
                                                "normal coasting sensor "
                                                "failed after speed zero\n");
                                        return -1;
                                }
                                checked_braking_coast_progress = 1;
                                continue;
                        }
                }

                int guard_sensor = -1;
                for (int offset =
                             job->target_route_offset + 1;
                     offset < runtime->route.node_count;
                     ++offset) {
                        if (dispatch_track[
                                    runtime->route.nodes[offset]]
                                    .type == NODE_SENSOR) {
                                guard_sensor = offset;
                                break;
                        }
                }
                if (!checked_braking_progress &&
                    guard_sensor >= 0) {
                        if (Tc2RouteMonitorInit(
                                    dispatch_track,
                                    &runtime->route,
                                    job->target_route_offset,
                                    guard_sensor, 0,
                                    &runtime->monitor) < 0) {
                                return -1;
                        }
                        runtime->monitor_terminal_offset =
                                guard_sensor;
                        runtime->leg_end_offset =
                                job->target_route_offset;
                        runtime->reservation_anchor_offset =
                                job->target_route_offset;
                        runtime->last_confirmed_tick = mock_now;
                        runtime->last_journal_sequence = 0;
                        runtime->target_seen = 1;
                        runtime->stop_purpose =
                                TC2_STOP_DESTINATION;
                        job->state = TC2_JOB_BRAKING;
                        job->current_route_offset =
                                job->target_route_offset;
                        job->current_node = job->target_node;
                        train_sensor_attributed_event_t event;
                        event.sensor_index =
                                runtime->route.nodes[
                                        guard_sensor];
                        event.train = 100;
                        event.generation =
                                job->plan_generation;
                        event.sequence = 1;
                        event.timestamp = 1;
                        mock_now += 200;
                        event.arrival_tick = mock_now;
                        int observation_status =
                                process_sensor_observation(
                                        slot, &event,
                                        event.arrival_tick,
                                        mock_now);
                        if (job->destination_offset_mm > 0) {
                                /*
                                 * The first sensor at or beyond the
                                 * route-node ceiling is already past the
                                 * interior-edge virtual destination.
                                 * It must fail closed and retain ownership,
                                 * not be accepted as normal braking
                                 * progress.
                                 */
                                if (observation_status >= 0 ||
                                    job->state != TC2_JOB_FAILED ||
                                    job->failure_reason !=
                                            TC2_FAILURE_SENSOR_SEQUENCE ||
                                    job->stop_trigger !=
                                            TC2_STOP_TRIGGER_FAILSAFE ||
                                    mock_reservations
                                                    .owner_by_node[
                                                            job
                                                                    ->target_node] !=
                                            job->train ||
                                    mock_reservations
                                                    .generation_by_train[
                                                            job
                                                                    ->train] !=
                                            job->plan_generation) {
                                        fprintf(stderr,
                                                "downstream virtual "
                                                "destination sensor was "
                                                "not fail-closed\n");
                                        return -1;
                                }
                        } else if (observation_status < 0 ||
                                   job->state != TC2_JOB_BRAKING ||
                                   !runtime->target_seen ||
                                   !runtime->target_corroborated ||
                                   job->current_route_offset !=
                                           guard_sensor) {
                                return -1;
                        }
                        checked_braking_progress = 1;
                }
        }
        if (!checked_branch_guard ||
            !checked_braking_progress ||
            !checked_braking_coast_progress) {
                fprintf(stderr,
                        "final guard coverage incomplete: branch=%d "
                        "downstream=%d coast=%d\n",
                        checked_branch_guard,
                        checked_braking_progress,
                        checked_braking_coast_progress);
                return -1;
        }
        return 0;
}

static int footprint_has_turnout_number(
        const track_route *footprint, int number) {
        for (int offset = 0; offset < footprint->node_count; ++offset) {
                if (dispatch_track[footprint->nodes[offset]].num ==
                    number) {
                        return 1;
                }
        }
        return 0;
}

static int check_double_turnout_interlock(void) {
        int checked_curved = 0;
        track_turnout_plan invalid;
        invalid.action_count = 2;
        invalid.actions[0].switch_number = 153;
        invalid.actions[0].direction = DIR_CURVED;
        invalid.actions[1].switch_number = 154;
        invalid.actions[1].direction = DIR_CURVED;
        if (turnout_plan_is_consistent(&invalid)) {
                fprintf(stderr,
                        "paired curved turnout plan was accepted\n");
                return -1;
        }

        for (int start = 0;
             start < TC2_DISPATCH_START_COUNT; ++start) {
                for (int destination = 0;
                     destination <
                             TC2_DISPATCH_DESTINATION_COUNT;
                     ++destination) {
                        reset_dispatch_test();
                        if (prepare_one_trip(
                                    120, start, destination, 40) != 0) {
                                fprintf(stderr,
                                        "paired-turnout fixture could not "
                                        "prepare A-F start=%d d%d\n",
                                        start, destination + 1);
                                return -1;
                        }
                        int slot = find_train_job(120);
                        if (slot < 0) {
                                fprintf(stderr,
                                        "paired-turnout fixture lost job\n");
                                return -1;
                        }
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];

                        /*
                         * Rolling authority intentionally does not own
                         * paired turnouts in distant future legs.  Every
                         * turnout inside the currently granted prefix must
                         * still include its physical mate.
                         */
                        for (int offset = 0;
                             offset <=
                                     runtime
                                             ->authority_end_offset;
                             ++offset) {
                                int number = dispatch_track[
                                        runtime->route.nodes[offset]].num;
                                int mate = paired_turnout_mate(number);
                                if (mate != 0 &&
                                    (!footprint_has_turnout_number(
                                             &runtime->safety_footprint,
                                             number) ||
                                     !footprint_has_turnout_number(
                                             &runtime->safety_footprint,
                                             mate))) {
                                        fprintf(stderr,
                                                "local authority omitted "
                                                "paired turnout %d/%d "
                                                "start=%d d%d end=%d "
                                                "offset=%d\n",
                                                number, mate, start,
                                                destination + 1,
                                                runtime
                                                        ->authority_end_offset,
                                                offset);
                                        return -1;
                                }
                        }

                        mock_switch_count = 0;
                        int leg_start = 0;
                        while (leg_start <=
                               runtime->authority_end_offset) {
                                int leg_end = TrackRouteMotionLegEnd(
                                        dispatch_track, &runtime->route,
                                        leg_start);
                                if (leg_end < leg_start) {
                                        fprintf(stderr,
                                                "invalid authorized motion "
                                                "leg %d/%d\n",
                                                leg_start, leg_end);
                                        return -1;
                                }
                                if (leg_end >
                                    runtime->authority_end_offset) {
                                        leg_end =
                                                runtime
                                                        ->authority_end_offset;
                                }
                                runtime->leg_start_offset = leg_start;
                                runtime->leg_end_offset = leg_end;
                                if (queue_turnout_plan_for_leg(slot) < 0) {
                                        fprintf(stderr,
                                                "authorized local turnout "
                                                "queue failed start=%d "
                                                "d%d leg=%d..%d end=%d\n",
                                                start,
                                                destination + 1,
                                                leg_start, leg_end,
                                                runtime
                                                        ->authority_end_offset);
                                        return -1;
                                }
                                if (leg_end >=
                                    runtime->authority_end_offset) {
                                        break;
                                }
                                leg_start = leg_end + 1;
                        }
                        for (int action = 0;
                             action < mock_switch_count; ++action) {
                                int mate = paired_turnout_mate(
                                        mock_switch_number[action]);
                                if (mate == 0 ||
                                    mock_switch_direction[action] != 'C') {
                                        continue;
                                }
                                if (action == 0 ||
                                    mock_switch_number[action - 1] != mate ||
                                    mock_switch_direction[action - 1] !=
                                            'S') {
                                        fprintf(stderr,
                                                "paired turnout command "
                                                "ordering failed at %d "
                                                "mate=%d\n",
                                                mock_switch_number[action],
                                                mate);
                                        return -1;
                                }
                                checked_curved = 1;
                        }
                }
        }

        /*
         * The currently shortest A-F/d1-d8 choices need not select every
         * central curved edge.  Exercise each real branch edge directly so
         * the interlock test cannot silently lose coverage when route costs
         * or destination-side tie breaking change.
         */
        checked_curved = 0;
        for (int number = 153; number <= 156; ++number) {
                reset_dispatch_test();
                int branch = -1;
                for (int node = 0; node < TRACK_MAX; ++node) {
                        if (dispatch_track[node].type == NODE_BRANCH &&
                            dispatch_track[node].num == number) {
                                branch = node;
                                break;
                        }
                }
                if (branch < 0 ||
                    !dispatch_track[branch]
                            .edge[DIR_CURVED].dest) {
                        fprintf(stderr,
                                "missing paired branch %d\n",
                                number);
                        return -1;
                }
                int curved = (int)(
                        dispatch_track[branch]
                                .edge[DIR_CURVED].dest -
                        dispatch_track);
                tc2_dispatch_runtime *runtime =
                        &dispatch_runtime[0];
                runtime->route.node_count = 2;
                runtime->route.nodes[0] = branch;
                runtime->route.nodes[1] = curved;
                runtime->route.distance_mm =
                        dispatch_track[branch]
                                .edge[DIR_CURVED].dist;
                runtime->route.optimization_cost_mm =
                        runtime->route.distance_mm;
                runtime->route.reversal_count = 0;
                runtime->route_valid = 1;
                runtime->leg_start_offset = 0;
                runtime->leg_end_offset = 1;
                mock_switch_count = 0;
                if (queue_turnout_plan_for_leg(0) < 0 ||
                    mock_switch_count != 2 ||
                    mock_switch_number[0] !=
                            paired_turnout_mate(number) ||
                    mock_switch_direction[0] != 'S' ||
                    mock_switch_number[1] != number ||
                    mock_switch_direction[1] != 'C') {
                        fprintf(stderr,
                                "direct paired command failed for %d "
                                "count=%d first=%d/%c second=%d/%c\n",
                                number, mock_switch_count,
                                mock_switch_number[0],
                                mock_switch_direction[0],
                                mock_switch_number[1],
                                mock_switch_direction[1]);
                        return -1;
                }
                track_route footprint;
                if (build_safety_footprint_for_route(
                            &runtime->route, 0, 1, 1, 0, 40,
                            &footprint) < 0 ||
                    !footprint_has_turnout_number(
                            &footprint, number) ||
                    !footprint_has_turnout_number(
                            &footprint,
                            paired_turnout_mate(number))) {
                        fprintf(stderr,
                                "direct paired footprint failed for %d\n",
                                number);
                        return -1;
                }
                ++checked_curved;
        }
        return checked_curved == 4 ? 0 : -1;
}

static int check_reversal_stop_and_missing_fail(void) {
        reset_dispatch_test();
        track_route unsafe_reversal;
        unsafe_reversal.node_count = 3;
        unsafe_reversal.nodes[0] =
                TrackFindNodeByName(dispatch_track, "C13");
        unsafe_reversal.nodes[1] =
                TrackFindNodeByName(dispatch_track, "C14");
        int c14 = unsafe_reversal.nodes[1];
        unsafe_reversal.nodes[2] =
                c14 >= 0 &&
                        dispatch_track[c14].edge[DIR_AHEAD].dest ?
                (int)(dispatch_track[c14]
                              .edge[DIR_AHEAD].dest -
                      dispatch_track) :
                -1;
        unsafe_reversal.distance_mm = 50;
        unsafe_reversal.optimization_cost_mm = 50;
        unsafe_reversal.reversal_count = 1;
        if (unsafe_reversal.nodes[0] < 0 ||
            unsafe_reversal.nodes[1] < 0 ||
            unsafe_reversal.nodes[2] < 0 ||
            dispatch_track[unsafe_reversal.nodes[2]].type !=
                    NODE_BRANCH ||
            reversal_turnout_clearance_is_safe_policy(
                    &unsafe_reversal, 2, 40, 0)) {
                fprintf(stderr,
                        "near-turnout reversal was not rejected\n");
                return -1;
        }
        track_route unsafe_current;
        unsafe_current.node_count = 3;
        unsafe_current.nodes[0] = unsafe_reversal.nodes[1];
        unsafe_current.nodes[1] = unsafe_reversal.nodes[2];
        unsafe_current.nodes[2] =
                (int)(dispatch_track[
                              unsafe_current.nodes[1]]
                              .edge[DIR_STRAIGHT].dest -
                      dispatch_track);
        unsafe_current.distance_mm = 50;
        unsafe_current.optimization_cost_mm = 50;
        unsafe_current.reversal_count = 0;
        track_turnout_plan no_confirmed_turnouts;
        no_confirmed_turnouts.action_count = 0;
        if (unsafe_current.nodes[2] < 0 ||
            unsafe_current.nodes[2] >= TRACK_MAX ||
            initial_turnouts_clear_of_carried_ambiguity(
                    &unsafe_current, 2, &unsafe_current,
                    &no_confirmed_turnouts)) {
                fprintf(stderr,
                        "CURRENT changed an unconfirmed turnout inside "
                        "its carried hold\n");
                return -1;
        }
        unsigned char unavailable[TRACK_MAX];
        for (int node = 0; node < TRACK_MAX; ++node) {
                unavailable[node] = 0;
        }
        int found_ambiguity_turnout_rejection = 0;
        for (int start = 0;
             start < TRAIN_SENSOR_COUNT &&
             !found_ambiguity_turnout_rejection; ++start) {
                for (int target = 0;
                     target < TRAIN_SENSOR_COUNT; ++target) {
                        track_route overlap_route;
                        int overlap_target = -1;
                        int overlap_destination = -1;
                        int overlap_distance = 0;
                        int overlap_cost = 0;
                        if (start == target ||
                            candidate_route(
                                    start, target, unavailable, 50, 1, 0,
                                    0, 0,
                                    &overlap_route,
                                    &overlap_target,
                                    &overlap_destination,
                                    &overlap_distance,
                                    &overlap_cost) < 0 ||
                            overlap_route.reversal_count < 1) {
                                continue;
                        }
                        tc2_dispatch_job_snapshot *overlap_job =
                                &dispatch_jobs[0];
                        tc2_dispatch_runtime *overlap_runtime =
                                &dispatch_runtime[0];
                        clear_job(overlap_job);
                        clear_runtime(overlap_runtime);
                        overlap_job->train = 109;
                        overlap_job->speed = 50;
                        overlap_job->target_node =
                                overlap_route.nodes[
                                        overlap_target];
                        overlap_job->target_route_offset =
                                overlap_target;
                        overlap_job->destination_route_offset =
                                overlap_destination;
                        overlap_job->destination_offset_mm = 0;
                        overlap_job->destination_distance_mm =
                                overlap_distance;
                        overlap_runtime->route =
                                overlap_route;
                        overlap_runtime->route_valid = 1;
                        overlap_runtime->leg_start_offset = 0;
                        overlap_runtime->command_speed = 50;
                        overlap_runtime->motion_speed_ceiling = 50;
                        if (init_leg_monitor(0, 0) == 0 &&
                            overlap_runtime->leg_end_offset <
                                    overlap_target &&
                            !next_leg_turnouts_clear_of_uncertain_train(
                                    0)) {
                                found_ambiguity_turnout_rejection = 1;
                                break;
                        }
                }
        }
        if (!found_ambiguity_turnout_rejection) {
                fprintf(stderr,
                        "no real false-reversal ambiguity corridor "
                        "rejected an overlapping next-leg turnout\n");
                return -1;
        }

        track_route selected;
        int target_offset = -1;
        int destination_route_offset = -1;
        int path_distance = 0;
        int path_cost = 0;
        int found = 0;
        for (int start = 0;
             start < TRAIN_SENSOR_COUNT && !found; ++start) {
                for (int target = 0;
                     target < TRAIN_SENSOR_COUNT; ++target) {
                        int first_leg_end;
                        int first_leg_distance;
                        if (start == target ||
                            candidate_route(
                                    start, target, unavailable, 50, 1, 0,
                                    0, 0,
                                    &selected, &target_offset,
                                    &destination_route_offset,
                                    &path_distance, &path_cost) < 0 ||
                            selected.reversal_count < 1 ||
                            (first_leg_end =
                                     TrackRouteMotionLegEnd(
                                             dispatch_track,
                                             &selected, 0)) <= 0 ||
                            first_leg_end >= target_offset ||
                            TrackRouteDistanceBetweenOffsets(
                                    dispatch_track, &selected, 0,
                                    first_leg_end,
                                    &first_leg_distance) < 0 ||
                            first_leg_distance <=
                                    Tc2MotionStopDistanceMm(50)) {
                                continue;
                        }
                        found = 1;
                        break;
                }
        }
        if (!found || path_distance < 0 || path_cost < 0) return -1;

        int slot = 0;
        tc2_dispatch_job_snapshot *job = &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime = &dispatch_runtime[slot];
        clear_job(job);
        clear_runtime(runtime);
        job->train = 110;
        job->speed = 50;
        job->state = TC2_JOB_RUNNING;
        job->target_node = selected.nodes[target_offset];
        job->target_route_offset = target_offset;
        job->destination_route_offset =
                destination_route_offset;
        job->destination_offset_mm = 0;
        job->destination_distance_mm = path_distance;
        job->route_distance_mm = path_distance;
        runtime->route = selected;
        runtime->route_valid = 1;
        runtime->leg_start_offset = 0;
        runtime->command_speed = job->speed;
        if (build_safety_footprint_for_route(
                    &runtime->route, 0, target_offset,
                    destination_route_offset, 0,
                    job->speed, &runtime->safety_footprint) < 0) {
                return -1;
        }
        track_reservation_conflict conflict;
        if (TrackReservationServerReserveWithGeneration(
                    1, &runtime->safety_footprint, job->train,
                    job->target_node, &conflict,
                    &job->plan_generation) != 0 ||
            init_leg_monitor(slot, 0) < 0 ||
            runtime->leg_end_offset >= target_offset ||
            can_health_is_safe(
                    slot, 1, mock_now) < 0) {
                return -1;
        }
        runtime->last_confirmed_tick = mock_now;
        runtime->launch_train_attribution_failure = 0;
        job->launch_attribution_unavailable_count = 0;
        int initial_tick = mock_now;
        int reversal_distance;
        int stop_distance =
                Tc2MotionStopDistanceMm(job->speed);
        int full_guard =
                Tc2MotionBrakingDistanceMm(job->speed);
        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, &runtime->route,
                    runtime->leg_start_offset,
                    runtime->leg_end_offset,
                    &reversal_distance) < 0 ||
            stop_distance < 0 || full_guard < stop_distance ||
            schedule_motion_deadlines(slot, initial_tick) < 0) {
                return -1;
        }
        int expected_braking_delta =
                Tc2MotionFastTravelTicks(
                        job->speed,
                        reversal_distance - stop_distance);
        if (expected_braking_delta <= 0 ||
            job->braking_at_tick !=
                    tick_after(
                            initial_tick,
                            expected_braking_delta)) {
                fprintf(stderr,
                        "reversal stop deadline did not use the real "
                        "elapsed approach distance\n");
                return -1;
        }
        int stop_deadline = job->braking_at_tick;
        mock_stop_confirmation_tick_advance = 7;
        mock_now = stop_deadline;
        process_running_jobs(mock_now);
        if (job->state != TC2_JOB_BRAKING ||
            !runtime->approach_sent ||
            runtime->command_speed != 0 ||
            runtime->stop_purpose != TC2_STOP_REVERSAL ||
            job->stop_sent_tick !=
                    tick_after(stop_deadline, 7) ||
            runtime->settle_at_tick !=
                    tick_after(
                            job->stop_sent_tick,
                            Tc2MotionStopSettleTicks(
                                    job->speed)) ||
            Tc2MotionStopSettleTicks(job->speed) <= 100 ||
            mock_reservations.owner_by_node[
                    runtime->route.nodes[
                            runtime->leg_end_offset]] !=
                    job->train) {
                return -1;
        }
        if (tick_reached(
                    stop_deadline,
                    job->watchdog_at_tick)) {
                fprintf(stderr,
                        "reversal missing-sensor stop was not before "
                        "the liveness watchdog\n");
                return -1;
        }
        /*
         * At the fast-bound command point the train is at most
         * stop_distance before the reversal. Its full protected stopping
         * envelope can therefore overrun the sensor by at most the model
         * uncertainty, which must already be owned in the forward guard.
         */
        track_route required_overrun;
        required_overrun.node_count = 1;
        required_overrun.nodes[0] =
                runtime->route.nodes[
                        runtime->leg_end_offset];
        required_overrun.distance_mm = 0;
        required_overrun.optimization_cost_mm = 0;
        required_overrun.reversal_count = 0;
        if (append_forward_guard_reachable(
                    &required_overrun,
                    required_overrun.nodes[0],
                    full_guard - stop_distance) < 0) {
                return -1;
        }
        for (int offset = 0;
             offset < required_overrun.node_count; ++offset) {
                if (mock_reservations.owner_by_node[
                            required_overrun.nodes[offset]] !=
                    job->train) {
                        fprintf(stderr,
                                "missing reversal stop envelope escaped "
                                "the reservation\n");
                        return -1;
                }
        }
        mock_now = runtime->settle_at_tick;
        process_braking_and_reversing(mock_now);
        if (job->state != TC2_JOB_FAILED ||
            job->failure_reason !=
                    TC2_FAILURE_SENSOR_SEQUENCE ||
            mock_reservations.owner_by_node[
                    job->target_node] != job->train) {
                return -1;
        }
        return 0;
}

static int check_complete_reversal_success_path(void) {
        if (TC2_REVERSE_SETTLE_TICKS != 50) {
                fprintf(stderr,
                        "TC2 reverse restart barrier must match the "
                        "validated 500 ms Track D decoder settle time\n");
                return -1;
        }
        unsigned char unavailable[TRACK_MAX];
        track_route selected;
        int target_offset = -1;
        int destination_route_offset = -1;
        int path_distance = 0;
        int path_cost = 0;
        int slot = 0;
        int found = 0;

        for (int start = 0;
             start < TRAIN_SENSOR_COUNT && !found; ++start) {
                for (int target = 0;
                     target < TRAIN_SENSOR_COUNT; ++target) {
                        reset_dispatch_test();
                        for (int node = 0; node < TRACK_MAX; ++node) {
                                unavailable[node] = 0;
                        }
                        int first_leg_end;
                        int first_leg_distance;
                        if (start == target ||
                            candidate_route(
                                    start, target, unavailable, 50, 1, 0,
                                    0, 0,
                                    &selected, &target_offset,
                                    &destination_route_offset,
                                    &path_distance, &path_cost) < 0 ||
                            selected.reversal_count < 1 ||
                            (first_leg_end =
                                     TrackRouteMotionLegEnd(
                                             dispatch_track,
                                             &selected, 0)) <= 0 ||
                            first_leg_end >= target_offset ||
                            TrackRouteDistanceBetweenOffsets(
                                    dispatch_track, &selected, 0,
                                    first_leg_end,
                                    &first_leg_distance) < 0 ||
                            first_leg_distance <=
                                    Tc2MotionStopDistanceMm(50)) {
                                continue;
                        }

                        tc2_dispatch_job_snapshot *job =
                                &dispatch_jobs[slot];
                        tc2_dispatch_runtime *runtime =
                                &dispatch_runtime[slot];
                        clear_job(job);
                        clear_runtime(runtime);
                        job->train = 111;
                        job->speed = 50;
                        job->state = TC2_JOB_RUNNING;
                        job->target_node =
                                selected.nodes[target_offset];
                        job->target_route_offset =
                                target_offset;
                        job->destination_route_offset =
                                destination_route_offset;
                        job->destination_offset_mm = 0;
                        job->destination_distance_mm =
                                path_distance;
                        job->route_distance_mm =
                                path_distance;
                        runtime->route = selected;
                        runtime->route_valid = 1;
                        runtime->leg_start_offset = 0;
                        runtime->command_speed = job->speed;
                        runtime->motion_speed_ceiling =
                                job->speed;
                        if (build_safety_footprint_for_route(
                                    &runtime->route, 0,
                                    target_offset,
                                    destination_route_offset, 0,
                                    job->speed,
                                    &runtime->safety_footprint) < 0) {
                                continue;
                        }
                        track_reservation_conflict conflict;
                        if (TrackReservationServerReserveWithGeneration(
                                    1, &runtime->safety_footprint,
                                    job->train, job->target_node,
                                    &conflict,
                                    &job->plan_generation) != 0 ||
                            init_leg_monitor(slot, 0) < 0 ||
                            runtime->leg_end_offset >=
                                    target_offset ||
                            !next_leg_turnouts_clear_of_uncertain_train(
                                    slot) ||
                            sensor_health_is_safe(
                                    slot,
                                    &mock_sensor_snapshot, 1,
                                    mock_now) < 0 ||
                            can_health_is_safe(
                                    slot, 1, mock_now) < 0) {
                                continue;
                        }
                        runtime->last_confirmed_tick =
                                mock_now;
                        runtime
                                ->launch_train_attribution_failure = 0;
                        job->launch_attribution_unavailable_count = 0;
                        found = 1;
                        break;
                }
        }
        if (!found || path_distance < 0 || path_cost < 0) {
                fprintf(stderr,
                        "could not find an executable reversal route\n");
                return -1;
        }

        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (schedule_motion_deadlines(slot, mock_now) < 0) {
                return -1;
        }

        unsigned int sequence = 0;
        for (int step = 0;
             step < TRACK_MAX &&
             !runtime->target_seen;
             ++step) {
                tc2_route_sensor_point next;
                tc2_route_sensor_point after;
                if (Tc2RouteExpectedSensors(
                            dispatch_track, &runtime->route,
                            runtime->monitor.confirmed_offset,
                            runtime->monitor_terminal_offset,
                            &next, &after) < 1) {
                        return -1;
                }
                int distance;
                if (TrackRouteDistanceBetweenOffsets(
                            dispatch_track, &runtime->route,
                            runtime->monitor.confirmed_offset,
                            next.route_offset, &distance) < 0) {
                        return -1;
                }
                int speed_bound =
                        runtime->speed_reduction_pending ?
                                runtime->motion_speed_ceiling :
                        runtime->command_speed > 0 ?
                                runtime->command_speed :
                                runtime->motion_speed_ceiling;
                int travel =
                        Tc2MotionFastTravelTicks(
                                speed_bound, distance);
                if (travel < 0) return -1;
                int arrival =
                        runtime->last_confirmed_tick +
                        travel + 2;
                if (job->state == TC2_JOB_RUNNING &&
                    tick_reached(
                            arrival,
                            job->braking_at_tick)) {
                        mock_now = job->braking_at_tick;
                        process_running_jobs(mock_now);
                        if (job->state !=
                                    TC2_JOB_BRAKING ||
                            runtime->stop_purpose !=
                                    TC2_STOP_REVERSAL ||
                            runtime->command_speed != 0) {
                                return -1;
                        }
                }
                if (job->state == TC2_JOB_BRAKING &&
                    tick_reached(
                            arrival,
                            runtime->settle_at_tick)) {
                        fprintf(stderr,
                                "normal reversal evidence could not "
                                "arrive inside the calibrated stop "
                                "settle envelope\n");
                        return -1;
                }
                mock_now = arrival;
                train_sensor_attributed_event_t event;
                event.sensor_index = next.node_index;
                event.train = job->train;
                event.generation = job->plan_generation;
                event.sequence = ++sequence;
                event.timestamp = (uint16_t)sequence;
                event.arrival_tick = arrival;
                if (process_sensor_observation(
                            slot, &event, arrival, arrival) < 0) {
                        return -1;
                }
        }
        if (job->state != TC2_JOB_BRAKING ||
            runtime->stop_purpose != TC2_STOP_REVERSAL ||
            !runtime->target_seen ||
            !job->position_estimated) {
                fprintf(stderr,
                        "reversal target did not enter conservative stop\n");
                return -1;
        }

        mock_now = runtime->settle_at_tick;
        mock_reverse_confirmation_tick_advance = 5;
        process_braking_and_reversing(mock_now);
        if (job->state != TC2_JOB_REVERSING ||
            job->reversals_completed != 1 ||
            job->current_leg != 1 ||
            runtime->reversal_phase !=
                    TC2_REVERSAL_PHASE_TURNOUT) {
                fprintf(stderr,
                        "settled reversal did not enter the stopped "
                        "turnout barrier\n");
                return -1;
        }
        if (runtime->turnout_batch_token != 0) {
                ++mock_now;
                process_braking_and_reversing(mock_now);
        }
        if (runtime->reverse_ready_at_tick < 0) {
                return -1;
        }
        int reverse_request_tick =
                runtime->reverse_ready_at_tick;
        mock_now = reverse_request_tick;
        process_braking_and_reversing(mock_now);
        if (mock_reverse_calls != 1 ||
            runtime->reversal_phase !=
                    TC2_REVERSAL_PHASE_SETTLE) {
                fprintf(stderr,
                        "mid-route reversal did not wait for and then "
                        "issue its direction command\n");
                return -1;
        }
        if (!tick_reached(
                    runtime->reverse_ready_at_tick,
                    tick_after(
                            tick_after(
                                    reverse_request_tick,
                                    5),
                            TC2_REVERSE_SETTLE_TICKS))) {
                fprintf(stderr,
                        "mid-route reverse settle began before CAN "
                        "confirmation\n");
                return -1;
        }
        mock_now = runtime->reverse_ready_at_tick;
        int resume_request_tick = mock_now;
        mock_positive_confirmation_tick_advance = 4;
        int positive_before_gate =
                mock_positive_speed_calls +
                mock_direct_positive_speed_calls;
        runtime->prelaunch_traffic_blocked = 1;
        process_braking_and_reversing(mock_now);
        if (job->state != TC2_JOB_REVERSING ||
            runtime->command_speed != 0 ||
            mock_positive_speed_calls +
                            mock_direct_positive_speed_calls !=
                    positive_before_gate) {
                fprintf(stderr,
                        "REVERSING bypassed the dynamic traffic "
                        "prelaunch gate\n");
                return -1;
        }
        runtime->prelaunch_traffic_blocked = 0;
        process_braking_and_reversing(mock_now);
        if (job->state != TC2_JOB_RUNNING ||
            runtime->command_speed != job->speed ||
            runtime->last_confirmed_tick !=
                    tick_after(resume_request_tick, 4)) {
                fprintf(stderr,
                        "confirmed next leg did not resume motion\n");
                return -1;
        }

        tc2_route_sensor_point outbound;
        tc2_route_sensor_point outbound_after;
        if (Tc2RouteExpectedSensors(
                    dispatch_track, &runtime->route,
                    runtime->monitor.confirmed_offset,
                    runtime->monitor_terminal_offset,
                    &outbound, &outbound_after) < 1) {
                return -1;
        }
        int outbound_distance;
        if (TrackRouteDistanceBetweenOffsets(
                    dispatch_track, &runtime->route,
                    runtime->monitor.confirmed_offset,
                    outbound.route_offset,
                    &outbound_distance) < 0) {
                return -1;
        }
        int outbound_ticks =
                Tc2MotionFastTravelTicks(
                        job->speed, outbound_distance);
        if (outbound_ticks < 0) return -1;
        train_sensor_attributed_event_t outbound_event;
        outbound_event.sensor_index = outbound.node_index;
        outbound_event.train = job->train;
        outbound_event.generation = job->plan_generation;
        outbound_event.sequence = ++sequence;
        outbound_event.timestamp = (uint16_t)sequence;
        outbound_event.arrival_tick =
                mock_now + outbound_ticks + 2;
        if (process_sensor_observation(
                    slot, &outbound_event,
                    outbound_event.arrival_tick,
                    outbound_event.arrival_tick) < 0 ||
            job->current_route_offset !=
                    outbound.route_offset ||
            runtime->reservation_anchor_offset <
                    runtime->leg_start_offset) {
                fprintf(stderr,
                        "outbound reversal evidence did not advance the "
                        "managed footprint\n");
                return -1;
        }
        return 0;
}

static int check_constructed_zero_motion_leading_barrier(void) {
        reset_dispatch_test();
        const int train = 122;
        const int speed = 120;
        const int slot = 0;
        track_route route;
        track_turnout_plan plan;
        int target = -1;
        int found = 0;
        int braking = Tc2MotionBrakingDistanceMm(speed);
        if (braking < 0) return -1;

        /*
         * The safe route selector normally prefers an already-directed
         * zero-cost target over reversing at the same physical sensor.
         * Construct the internal edge case explicitly so the combined
         * reverse-settle and nonempty turnout-confirmation barriers remain
         * regression tested without distorting route choice.
         */
        for (int start = 0;
             start < TRAIN_SENSOR_COUNT && !found; ++start) {
                int reverse = physical_reverse_index(start);
                if (reverse < 0 ||
                    reverse >= TRAIN_SENSOR_COUNT) {
                        continue;
                }
                route.node_count = 2;
                route.nodes[0] = start;
                route.nodes[1] = reverse;
                route.distance_mm = 0;
                route.optimization_cost_mm =
                        TC2_REVERSAL_PENALTY_MM;
                route.reversal_count = 1;
                int represented =
                        TrackExtendRouteAhead(
                                dispatch_track, &route,
                                braking);
                if (represented < braking ||
                    build_turnout_plan_range_checked(
                            &route, 1,
                            route.node_count - 1,
                            &plan) < 0 ||
                    plan.action_count < 1) {
                        continue;
                }
                target = reverse;
                found = 1;
        }
        if (!found) {
                fprintf(stderr,
                        "could not construct a zero-motion leading route "
                        "with a turnout extension\n");
                return -1;
        }

        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        clear_job(job);
        clear_runtime(runtime);
        job->train = train;
        job->speed = speed;
        job->state = TC2_JOB_PREPARING;
        job->target_node = target;
        job->target_route_offset = 1;
        job->destination_route_offset = 1;
        job->destination_offset_mm = 0;
        job->destination_distance_mm = 0;
        job->current_node = target;
        job->current_route_offset = 1;
        job->route_distance_mm = 0;
        runtime->route = route;
        runtime->route_valid = 1;
        runtime->start_node = route.nodes[0];
        runtime->leg_start_offset = 1;
        runtime->command_speed = speed;
        runtime->motion_speed_ceiling = speed;
        if (init_leg_monitor(
                    slot,
                    mock_sensor_snapshot.attributed_count) < 0 ||
            build_safety_footprint_for_route(
                    &route, 0, 1, 1, 0, speed,
                    &runtime->safety_footprint) < 0) {
                return -1;
        }
        track_reservation_conflict conflict;
        unsigned int generation = 0;
        if (TrackReservationServerReserveWithGeneration(
                    1, &runtime->safety_footprint,
                    train, target, &conflict,
                    &generation) != 0 ||
            generation == 0) {
                return -1;
        }
        job->plan_generation = generation;
        if (sensor_health_is_safe(
                    slot, &mock_sensor_snapshot,
                    1, mock_now) < 0 ||
            can_health_is_safe(
                    slot, 1, mock_now) < 0) {
                return -1;
        }
        runtime->prepare_attributed_sequence =
                mock_sensor_snapshot.attributed_count;
        runtime->prepare_attribution_unavailable_count =
                mock_sensor_snapshot
                        .attribution_unavailable_count;
        runtime->prepare_unattributed_count =
                mock_sensor_snapshot.unattributed_count;
        for (int sensor = 0;
             sensor < TRAIN_SENSOR_COUNT; ++sensor) {
                runtime->prepare_sensor_state[sensor] =
                        mock_sensor_snapshot
                                .sensor_state[sensor];
        }

        mock_reverse_confirmation_tick_advance = 5;
        runtime->prelaunch_reverse_pending = 1;
        runtime->prelaunch_turnout_settle_at_tick = -1;
        runtime->prelaunch_reverse_ready_at_tick = -1;
        runtime->zero_motion_arrival_pending = 1;
        runtime->zero_motion_arrival_ready_at_tick = mock_now;
        mock_turnout_auto_complete = 0;
        int turnout_token =
                queue_turnout_plan_for_leg(slot);
        if (turnout_token <= 0) return -1;
        runtime->turnout_batch_token =
                (unsigned int)turnout_token;

        process_preparing_jobs(mock_now);
        if (job->state != TC2_JOB_PREPARING ||
            mock_reverse_calls != 0 ||
            mock_positive_speed_calls != 0 ||
            runtime->turnout_batch_token == 0) {
                fprintf(stderr,
                        "constructed zero-motion route reversed before "
                        "turnout confirmation\n");
                return -1;
        }
        mock_turnout_status.state =
                CAN_BATCH_COMPLETE;
        mock_turnout_status.confirmed =
                mock_turnout_status.total;
        process_preparing_jobs(mock_now);
        if (job->state != TC2_JOB_PREPARING ||
            mock_reverse_calls != 0 ||
            runtime->turnout_batch_token != 0 ||
            runtime
                    ->prelaunch_turnout_settle_at_tick <
                    0) {
                fprintf(stderr,
                        "turnout confirmation bypassed the mechanical "
                        "settle barrier before leading reverse\n");
                return -1;
        }
        int turnout_settle =
                runtime
                        ->prelaunch_turnout_settle_at_tick;
        mock_now = turnout_settle - 1;
        process_preparing_jobs(mock_now);
        if (job->state != TC2_JOB_PREPARING ||
            mock_reverse_calls != 0) {
                fprintf(stderr,
                        "leading reverse ran before turnout settle\n");
                return -1;
        }
        mock_now = turnout_settle;
        process_preparing_jobs(mock_now);
        int reverse_ready =
                runtime
                        ->prelaunch_reverse_ready_at_tick;
        if (job->state != TC2_JOB_PREPARING ||
            runtime->prelaunch_reverse_pending ||
            mock_reverse_calls != 1 ||
            reverse_ready !=
                    tick_after(
                            tick_after(turnout_settle, 5),
                            TC2_REVERSE_SETTLE_TICKS) ||
            mock_positive_speed_calls != 0 ||
            !runtime->zero_motion_arrival_pending) {
                fprintf(stderr,
                        "confirmed leading reverse did not enter its "
                        "direction settle barrier\n");
                return -1;
        }
        mock_now = reverse_ready - 1;
        process_preparing_jobs(mock_now);
        if (job->state != TC2_JOB_PREPARING) {
                return -1;
        }
        mock_now = reverse_ready;
        process_preparing_jobs(mock_now);
        if (job->state != TC2_JOB_ARRIVED ||
            runtime->zero_motion_arrival_pending ||
            mock_positive_speed_calls != 0 ||
            mock_reverse_calls != 1 ||
            !job->hold_active) {
                fprintf(stderr,
                        "constructed zero-motion route did not finish "
                        "after reverse settle\n");
                return -1;
        }
        return 0;
}

static int check_planned_zero_motion_leading_barrier(void) {
        /*
         * A same-anchor CURRENT plan is no longer zero distance: d1-d8 are
         * physical points beyond their anchor sensors.  Preserve the
         * leading reverse/turnout barrier, but reject the old immediate
         * ARRIVED shortcut.
         */
        reset_dispatch_test();
        int old_node =
                TrackFindNodeByName(
                        dispatch_track, "C10");
        if (old_node < 0 ||
            force_exact_directed_hold(
                    121, old_node, 8) < 0) {
                return -1;
        }
        int slot = find_train_job(121);
        tc2_dispatch_request current;
        clear_request(
                &current, TC2_DISPATCH_MSG_STAGE);
        current.train = 121;
        current.start_index =
                TC2_DISPATCH_START_CURRENT;
        current.speed = 50;
        current.destination_index = 3;
        if (stage_job(&current) < 0) return -1;
        dispatch_jobs[slot].state =
                TC2_JOB_WAITING;
        dispatch_jobs[slot].queue_sequence =
                ++dispatch_queue_sequence;
        dispatch_jobs[slot].job_launch_epoch = 1;
        dispatch_runtime[slot].queue_sequence =
                dispatch_jobs[slot].queue_sequence;
        dispatch_runtime[slot].wait_since_tick =
                mock_now;
        dispatch_runtime[slot].launch_epoch = 1;
        mock_reverse_confirmation_tick_advance = 3;
        mock_turnout_auto_complete = 0;
        int prepare_tick = mock_now;
        if (prepare_waiting_job(
                    slot, prepare_tick) != 0) {
                return -1;
        }
        tc2_dispatch_job_snapshot *job =
                &dispatch_jobs[slot];
        tc2_dispatch_runtime *runtime =
                &dispatch_runtime[slot];
        if (runtime->route.node_count < 2 ||
            runtime->route.nodes[0] != old_node ||
            job->prediction_plan_valid ||
            job->prediction_execution_active ||
            runtime->leg_start_offset != 0 ||
            job->target_route_offset != 0 ||
            job->destination_route_offset <=
                    job->target_route_offset ||
            job->destination_offset_mm != 76 ||
            job->destination_distance_mm != 76 ||
            job->route_distance_mm != 76 ||
            job->state != TC2_JOB_PREPARING ||
            runtime->zero_motion_arrival_pending ||
            mock_reverse_calls != 0 ||
            mock_positive_speed_calls != 0 ||
            runtime->zero_motion_arrival_ready_at_tick != -1) {
                fprintf(stderr,
                        "same-anchor virtual destination used the old "
                        "zero-motion arrival shortcut: nodes=%d "
                        "leg_start=%d target=%d destination=%d "
                        "offset=%d distance=%d/%d state=%d pending=%d "
                        "turnout=%u/%d reverse=%d positive=%d ready=%d\n",
                        runtime->route.node_count,
                        runtime->leg_start_offset,
                        job->target_route_offset,
                        job->destination_route_offset,
                        job->destination_offset_mm,
                        job->destination_distance_mm,
                        job->route_distance_mm, job->state,
                        runtime->zero_motion_arrival_pending,
                        runtime->turnout_batch_token,
                        mock_turnout_status.total,
                        mock_reverse_calls,
                        mock_positive_speed_calls,
                        runtime->zero_motion_arrival_ready_at_tick);
                return -1;
        }
        return 0;
}

